// Where the orgs server is.
//
// Worg is served two ways and they want different answers. Built and embedded
// into the orgs binary, the page comes from the orgs server itself, so its own
// origin is the api - and using it keeps the build working whatever port the
// server was started on, which a hardcoded one does not. Under the react dev
// server the page comes from a port with no api behind it, so the connection
// is the orgs default on the same host.
//
// REACT_APP_ORGS_URL overrides both, for pointing a dev server at a server
// somewhere else without editing this file.
const DEV_PORTS = ['3000', '3030'];
const DEFAULT_PORT = '8010';

function orgsUrl(): string {
    const fromEnv = process.env.REACT_APP_ORGS_URL;
    if (fromEnv) {
        return fromEnv.replace(/\/+$/, '');
    }
    if (typeof window === 'undefined' || !window.location) {
        return `http://localhost:${DEFAULT_PORT}`;
    }
    const loc = window.location;
    // A page opened off the filesystem has no origin worth talking to.
    if (loc.protocol !== 'http:' && loc.protocol !== 'https:') {
        return `http://localhost:${DEFAULT_PORT}`;
    }
    if (DEV_PORTS.indexOf(loc.port) >= 0) {
        return `${loc.protocol}//${loc.hostname}:${DEFAULT_PORT}`;
    }
    return loc.origin;
}

export class Sets {
    public static allowSelfSigned: boolean = true;
    public static orgsConnection: string = orgsUrl();
}
