// The engine: a canvas, a render loop, and everything that has to happen inside
// one frame.
//
// It is a plain class rather than a component on purpose. The loop touches every
// star several times a frame and eases a dozen values per star; routing any of
// that through React state would be a re-render per frame of a tree with four
// thousand things in it. So React owns the chrome - the toolbar, the legend, the
// timeline, the panel - and this owns the canvas, the tooltip and the caption,
// which are the three things that move at frame rate.
//
// Everything React needs back comes through the host callbacks, and each of those
// fires on a *change* rather than on a frame.

import { fuzzyScore } from '../fuzzy';
import {
    BACKDROP_COUNT, BACKDROP_RADIUS_MIN, BACKDROP_RADIUS_RANGE,
    DYING_MAX, DYING_RATE, FOCAL, STEP_BUDGET_MS, TIERCAP, ZMAX, ZMIN,
} from './constants';
import { coolAlpha, physicsStep } from './forces';
import { Galaxy, Remembered, remember } from './build';
import { hash } from './hash';
import { hull } from './hull';
import { lookOf } from './palette';
import { lensPoint, project } from './projection';
import { ShapeState } from './shapes';
import {
    BackdropStar, BlackHole, CameraState, DyingNode, FamilyLook, Palette,
    Particle, Projectable, StarLink, StarNode, StarmapSettings,
} from './types';

// What the engine tells the page about.
export interface StarmapHost {
    // A star was clicked. Opening it is the page's business - it knows about
    // panels and this does not.
    onOpen(star: StarNode): void;
    // A star was right-clicked, at these client coordinates.
    onMenu(star: StarNode, x: number, y: number): void;
    // The timeline moved, or stopped playing.
    onTime(pos: number, playing: boolean): void;
    // Flight mode was entered or left - by the W key as much as by a button, so
    // the page cannot know without being told.
    onFlight(flying: boolean): void;
    // The pointer crossed into a constellation. Sounding it is the page's, since
    // the page owns the audio engine.
    onConstellation(look: FamilyLook): void;
    // A still was asked for and is ready, as a data url.
    onShot(url: string): void;
}

// What colour a star is drawn. The engine never decides this: constellation
// colour and todo-keyword colour are both reasonable and which one is on is a
// setting, so the page hands over a function.
export type ColourFn = (n: StarNode) => FamilyLook;

const EMPTY_GALAXY: Galaxy = {
    nodes: [], links: [], families: [], dates: [], datedCount: 0, anchors: [],
    total: 0, truncated: false, swallowed: 0, eaten: [], skippedLinks: 0,
};

function scratch(): Projectable {
    return { x: 0, y: 0, z: 0, sx: 0, sy: 0, ss: 1, sd: 0, near: false, nf: 1 };
}

export class StarmapEngine {
    private canvas: HTMLCanvasElement;
    private ctx: CanvasRenderingContext2D;
    private wrap: HTMLElement;
    private tip: HTMLElement | null;
    private caption: HTMLElement | null;
    private host: StarmapHost;

    // The live settings object. A slider writes straight into this, which is why
    // dragging one costs nothing: no state, no render, the next frame just reads
    // a different number.
    public S: StarmapSettings;

    private galaxy: Galaxy = EMPTY_GALAXY;
    private pal: Palette = {};
    private colourFn: ColourFn;

    private W = 0;
    private H = 0;
    private DPR = 1;
    private reduceMotion = false;

    // The fog is painted at 70% and scaled up. Fog is soft anyway and this
    // quarters the fill cost, which is what the zoom lag was made of.
    private fogCv: HTMLCanvasElement;
    private fogCtx: CanvasRenderingContext2D;
    // The two buffers the pixel lensing needs.
    private warpCv: HTMLCanvasElement | null = null;
    private warpCtx: CanvasRenderingContext2D | null = null;
    private warp2: HTMLCanvasElement | null = null;
    private warp2Ctx: CanvasRenderingContext2D | null = null;

    private ro: ResizeObserver | null = null;
    private raf = 0;
    private dead = false;
    private t0 = 0;

    // Camera.
    private yaw = 0.4;
    private pitch = 0.18;
    private targetYaw = 0.4;
    private targetPitch = 0.18;
    private zoom = 1;
    private targetZoom = 1;
    private ctr = { x: 0, y: 0, z: 0 };
    private gCtr = { x: 0, y: 0, z: 0 };
    private focusIdx = -1;
    private flying = false;
    // How wide the galaxy currently is *on screen*, measured in drawStars and
    // used by the fit on the next frame.
    private screenR = 0;
    // Whether the camera has been left alone. A galaxy expands a long way while
    // it settles - four thousand stars all pushing on each other - so the zoom
    // follows it out until it stops moving, and then stops following. The moment
    // somebody scrolls or drags, it is their camera and this gets out of the way.
    private userMoved = false;
    // Whether the fit has caught up with the galaxy. Until it has, the camera
    // keeps correcting even on a settled one - which is what makes arriving,
    // regrouping and soloing all land on a picture that fits.
    private fitted = false;
    private cam = { x: 0, y: 0, z: 0 };
    private vel = { x: 0, y: 0, z: 0 };
    private keys = new Set<string>();

    // Interaction.
    private hover = -1;
    private lastBlip = -1;
    private dragging = false;
    private px = 0;
    private py = 0;
    private downX = 0;
    private downY = 0;
    private idleT = 0;
    private mouseOver = false;
    private ptrs = new Map<number, { x: number; y: number }>();
    private pinchStart = 0;
    private pinchZoom0 = 1;

    // Simulation.
    private alpha = 1;
    private stepAcc = 0;
    private shapeState: ShapeState = {};
    private idleFrames = 0;

    // Scenery.
    private backdrop: BackdropStar[] = [];
    private particles: Particle[] = [];
    private shoot: { x: number; y: number; dx: number; dy: number; t: number } | null = null;
    private shootTimer = 1600;
    private hole: BlackHole = {
        x: 0, y: 0, z: 0, tx: 0, ty: 0, tz: 0, n: 0, eaten: [],
        init: false, scr: 0, sx: 0, sy: 0, ss: 1, sd: 0, near: false, nf: 1,
    };
    private dying: DyingNode[] = [];

    // Sprites, cached by colour rather than by constellation: the colour may come
    // from a keyword instead, and either way the number of distinct ones is small.
    private puffs = new Map<string, HTMLCanvasElement>();
    private glows = new Map<string, HTMLCanvasElement>();

    // Timeline.
    private timePos = 0;
    private playing = false;
    private playAcc = 0;

    // Solo: the one thing shown, and what "thing" means - a constellation, or a
    // todo keyword. Both, because the legend shows whatever colour currently
    // means, and a legend you cannot click is half a legend. Plus the eased fade
    // of every constellation not in it.
    private solo: string | null = null;
    private soloBy: 'fam' | 'status' = 'fam';
    private famF: Record<string, number> = {};

    // The tour.
    private tour: { step: number; hold: number } | null = null;

    // Fixed draw order: big stars behind, small in front, decided once. Sorting by
    // camera depth swaps the order of overlapping discs between frames, which
    // reads as the colours flickering.
    private ord: number[] = [];

    // Per-name state the ring letters need to stay still: which way a name faces,
    // how faded it is, whether it is currently lit and how long it has been out.
    private famLC: Record<string, { adv: number[]; tot: number }> = {};
    private famFlip: Record<string, boolean> = {};
    private famFade: Record<string, number> = {};
    private famOn: Record<string, boolean> = {};
    private famOffAge: Record<string, number> = {};

    private wantShot = false;
    private capTimer: ReturnType<typeof setTimeout> | null = null;

    constructor(
        canvas: HTMLCanvasElement,
        wrap: HTMLElement,
        tip: HTMLElement | null,
        caption: HTMLElement | null,
        settings: StarmapSettings,
        colourFn: ColourFn,
        host: StarmapHost,
    ) {
        this.canvas = canvas;
        this.ctx = canvas.getContext('2d') as CanvasRenderingContext2D;
        this.wrap = wrap;
        this.tip = tip;
        this.caption = caption;
        this.S = settings;
        this.colourFn = colourFn;
        this.host = host;

        this.fogCv = document.createElement('canvas');
        this.fogCtx = this.fogCv.getContext('2d') as CanvasRenderingContext2D;

        this.reduceMotion = typeof window.matchMedia === 'function'
            && window.matchMedia('(prefers-reduced-motion: reduce)').matches;

        for (let i = 0; i < BACKDROP_COUNT; i++) {
            const u = hash(i, 7) * 2 - 1;
            const th = hash(i, 13) * 6.283;
            const rr = BACKDROP_RADIUS_MIN + hash(i, 29) * BACKDROP_RADIUS_RANGE;
            const sq = Math.sqrt(Math.max(0, 1 - u * u));
            this.backdrop.push({
                x: Math.cos(th) * sq * rr,
                y: u * rr * 0.85,
                z: Math.sin(th) * sq * rr,
                b: 0.25 + hash(i, 3) * 0.6,
                l: i % 3,
            });
        }
        this.rebuildParticles();
        this.resize();
        this.bind();
    }

    // ---------------------------------------------------------------------
    // Lifecycle
    // ---------------------------------------------------------------------

    start(): void {
        this.t0 = performance.now();
        this.raf = requestAnimationFrame(this.frame);
    }

    destroy(): void {
        this.dead = true;
        if (this.raf) cancelAnimationFrame(this.raf);
        if (this.ro) this.ro.disconnect();
        if (this.capTimer) clearTimeout(this.capTimer);
        this.unbind();
    }

    isDead(): boolean {
        return this.dead;
    }

    resize(): void {
        this.DPR = Math.min(window.devicePixelRatio || 1, 2);
        this.W = this.wrap.clientWidth || 600;
        this.H = this.wrap.clientHeight || 400;
        this.canvas.width = this.W * this.DPR;
        this.canvas.height = this.H * this.DPR;
        this.fogCv.width = Math.max(2, Math.round(this.W * 0.7));
        this.fogCv.height = Math.max(2, Math.round(this.H * 0.7));
    }

    // ---------------------------------------------------------------------
    // Data
    // ---------------------------------------------------------------------

    // Hand over a new galaxy. Stars that are still there keep their motion, which
    // buildGalaxy does; what happens here is the rest of it - the ones that have
    // gone spiral into the hole, and the physics is warmed rather than restarted.
    setData(next: Galaxy, pal: Palette): void {
        const had = this.galaxy.nodes.length > 0;
        const before = new Set(this.galaxy.nodes.map(n => n.id));
        const now = new Set(next.nodes.map(n => n.id));

        if (had) {
            for (const n of this.galaxy.nodes) {
                if (now.has(n.id)) continue;
                if (this.dying.length > DYING_MAX) this.dying.shift();
                this.dying.push({
                    x: n.x, y: n.y, z: n.z,
                    fam: n.fam, r: n.r, t: 0, ph: Math.random() * 6.283,
                });
            }
            const born = next.nodes.filter(n => !before.has(n.id));
            if (born.length === 1) {
                this.showCaption(`“${born[0].label}”`, 'a star ignites', 3200);
            } else if (born.length > 1) {
                this.showCaption(`${born.length} stars ignite`, '', 2600);
            }
        }

        this.galaxy = next;
        this.pal = pal;
        this.hole.n = next.swallowed;
        this.hole.eaten = next.eaten;
        this.famF = {};
        for (const f of next.families) this.famF[f.key] = 0;
        this.shapeState.famOrder = next.families.map(f => f.key);
        this.shapeState.clR = 0;
        this.ord = this.order();
        this.timePos = Math.max(0, next.dates.length - 1);
        this.applyTime();
        this.alpha = had
            ? Math.max(this.alpha, 0.3)
            : (next.nodes.length > 2500 ? 0.6 : 1);
        if (had) this.focusIdx = -1;
        // A different galaxy is a different size, so the fit starts again.
        this.fitted = false;
        if (!had) this.userMoved = false;
    }

    // What the last galaxy's stars were doing, to be handed back to buildGalaxy.
    memory(): Remembered {
        return remember(this.galaxy.nodes);
    }

    data(): Galaxy {
        return this.galaxy;
    }

    setPalette(pal: Palette): void {
        this.pal = pal;
        // The sprites are the palette baked into pixels, so they go with it.
        this.puffs.clear();
        this.glows.clear();
    }

    setColourFn(fn: ColourFn): void {
        this.colourFn = fn;
        this.puffs.clear();
        this.glows.clear();
    }

    private order(): number[] {
        const ns = this.galaxy.nodes;
        return ns.map((_, i) => i).sort((a, b) => (ns[b].r - ns[a].r) || (a - b));
    }

    // ---------------------------------------------------------------------
    // Controls the page drives
    // ---------------------------------------------------------------------

    // Warm the physics back up. Anything that changes where stars should be has
    // to, or the change is invisible on a settled galaxy.
    reheat(to: number = 0.55): void {
        this.alpha = Math.max(this.alpha, to);
    }

    setShape(name: string): void {
        this.S.shape = name;
        this.alpha = 1;
        this.fitted = false;
        this.shapeState.clR = 0;
        // The helix's strands re-freeze, or an old winding fights the new one.
        for (const n of this.galaxy.nodes) n.hxA = undefined;
        // A flat shape seen edge-on is a line. Tilt into it, once.
        if (name !== 'natural' && this.targetPitch < 0.35) this.targetPitch = 0.55;
    }

    rebuildParticles(): void {
        this.particles.length = 0;
        const n = this.reduceMotion ? 0 : Math.round(this.S.comets);
        for (let i = 0; i < n; i++) {
            this.particles.push({ l: i * 97, t: (i * 0.137) % 1, sp: 0.0012 + ((i * 53) % 100) / 100 * 0.002 });
        }
    }

    // Blow the galaxy apart. It puts itself back together, which is the point.
    boom(): void {
        this.alpha = 1;
        for (const n of this.galaxy.nodes) {
            const d = Math.sqrt(n.x * n.x + n.y * n.y + n.z * n.z) || 1;
            const k = 26 + Math.random() * 20;
            n.vx += n.x / d * k + (Math.random() - 0.5) * 10;
            n.vy += n.y / d * k + (Math.random() - 0.5) * 10;
            n.vz += n.z / d * k + (Math.random() - 0.5) * 10;
        }
    }

    shot(): void {
        this.wantShot = true;
    }

    setSolo(key: string | null, by: 'fam' | 'status' = 'fam'): void {
        this.solo = key;
        this.soloBy = by;
    }

    soloed(): string | null {
        return this.solo;
    }

    setTime(pos: number): void {
        this.timePos = pos;
        this.playing = false;
        this.hideCaption();
        this.applyTime();
        this.host.onTime(this.timePos, false);
    }

    togglePlay(): void {
        if (this.playing) {
            this.playing = false;
            this.host.onTime(this.timePos, false);
            return;
        }
        this.playing = true;
        if (this.timePos >= this.galaxy.dates.length - 1) {
            this.timePos = 0;
            this.applyTime();
        }
        this.host.onTime(this.timePos, true);
    }

    // What the timeline is showing: the date, and how many stars have been born
    // by it. Read by the page when it is told the position moved.
    timeLabel(): { date: string; visible: number; last: boolean } {
        const dates = this.galaxy.dates;
        const date = dates[this.timePos] || '';
        let visible = 0;
        for (const n of this.galaxy.nodes) visible += n.vis;
        return { date, visible, last: this.timePos >= dates.length - 1 };
    }

    private applyTime(): void {
        const cur = this.galaxy.dates[this.timePos];
        if (cur === undefined) {
            for (const n of this.galaxy.nodes) n.vis = 1;
            return;
        }
        for (const n of this.galaxy.nodes) n.vis = n.d !== '' && n.d <= cur ? 1 : 0;
    }

    // The search, using worg's own matcher rather than a substring test - so the
    // letters that find a heading in the palette find it here.
    search(query: string, limit: number = 8): number[] {
        const q = query.trim();
        if (q === '') return [];
        const scored: [number, number][] = [];
        this.galaxy.nodes.forEach((n, i) => {
            const s = fuzzyScore(q, n.label);
            if (s !== null) scored.push([s, i]);
        });
        scored.sort((a, b) => (b[0] - a[0]) || (a[1] - b[1]));
        return scored.slice(0, limit).map(([, i]) => i);
    }

    flyTo(i: number): void {
        this.exitFlight();
        this.focusIdx = i;
        this.userMoved = true;
        this.targetZoom = 2.2;
    }

    clearFocus(): void {
        this.focusIdx = -1;
        // Back to the whole sky rather than to a zoom of one, which on a big
        // galaxy is not "out" at all.
        this.userMoved = false;
        this.fitted = false;
    }

    home(): void {
        this.exitFlight();
        this.focusIdx = -1;
        this.targetYaw = 0.4;
        this.targetPitch = 0.18;
        this.userMoved = false;
        this.fitted = false;
    }

    // Put the whole galaxy on the screen.
    //
    // Without this the camera arrives at a zoom of 1 whatever it is looking at,
    // which on a four thousand star database is somewhere inside the core - the
    // galaxy is all around you, and nothing on screen says that scrolling out is
    // what you want.
    //
    // It corrects what is *on screen* rather than computing a zoom from the
    // galaxy's world radius, because the projection is perspective: the near half
    // of a galaxy is magnified by as much as two, so a zoom worked out from the
    // world radius puts the front of it off both edges. A ratio against the
    // measured extent needs to know nothing about the projection at all, and is
    // right again by itself after a shape change, a solo or a timeline scrub.
    //
    // The measure is the 90th percentile, so one star flung out by a shape change
    // cannot shrink everything else to a dot.
    private fitZoom(): void {
        if (this.screenR <= 0) return;
        const want = 0.44 * Math.min(this.W, this.H);
        const ratio = want / this.screenR;
        // Eased rather than jumped: this runs every frame while the galaxy is
        // still moving, and a hard set would fight the zoom easing below.
        const step = Math.max(0.5, Math.min(2, ratio));
        this.targetZoom = Math.min(ZMAX, Math.max(ZMIN, this.targetZoom * step));
    }

    // How far the galaxy reaches from the middle of the screen. Measured over the
    // stars that were actually drawn, once a frame.
    private measureExtent(): void {
        const nodes = this.galaxy.nodes;
        if (!nodes.length) { this.screenR = 0; return; }
        const cx = this.W / 2, cy = this.H / 2;
        const rs: number[] = [];
        // A sample rather than the lot: four thousand hypots a frame to place a
        // camera is four thousand too many, and a ninth of them answers the same.
        const stride = Math.max(1, Math.floor(nodes.length / 400));
        for (let i = 0; i < nodes.length; i += stride) {
            const n = nodes[i];
            if (!n.vis || n.near) continue;
            rs.push(Math.hypot(n.sx - cx, n.sy - cy));
        }
        if (!rs.length) { this.screenR = 0; return; }
        rs.sort((a, b) => a - b);
        this.screenR = rs[Math.floor(rs.length * 0.9)] || rs[rs.length - 1];
    }

    starAt(i: number): StarNode | undefined {
        return this.galaxy.nodes[i];
    }

    // The tour: one stop per constellation, at its busiest star.
    toggleTour(): boolean {
        if (this.tour) {
            this.tourStop();
            return false;
        }
        this.exitFlight();
        this.playing = false;
        this.host.onTime(this.timePos, false);
        this.tourGo(0);
        return this.tour !== null;
    }

    touring(): boolean {
        return this.tour !== null;
    }

    private tourStop(): void {
        this.tour = null;
        this.focusIdx = -1;
        this.userMoved = false;
        this.fitted = false;
        this.hideCaption();
    }

    private tourGo(step: number): void {
        const fams = this.galaxy.families;
        if (step >= fams.length) {
            this.tourStop();
            this.showCaption('the whole sky', 'end of tour', 3600);
            return;
        }
        this.tour = { step, hold: 0 };
        const key = fams[step].key;
        const members = this.galaxy.nodes.filter(n => n.fam === key);
        if (members.length === 0) {
            this.tourGo(step + 1);
            return;
        }
        let inner = 0;
        for (const l of this.galaxy.links) {
            if (this.galaxy.nodes[l.s].fam === key && this.galaxy.nodes[l.t].fam === key) inner++;
        }
        const hub = members.reduce((a, b) => (b.w > a.w ? b : a), members[0]);
        this.focusIdx = this.galaxy.nodes.indexOf(hub);
        this.targetZoom = 1.8;
        this.showCaption(
            fams[step].name,
            `${members.length} stars · ${inner} threads within`,
            0,
        );
    }

    // ---------------------------------------------------------------------
    // Captions
    // ---------------------------------------------------------------------

    private showCaption(main: string, sub: string, ms: number): void {
        const el = this.caption;
        if (!el) return;
        el.textContent = '';
        const m = document.createElement('span');
        m.textContent = main;
        el.appendChild(m);
        if (sub) {
            const s = document.createElement('span');
            s.className = 'sm-sub';
            s.textContent = sub;
            el.appendChild(s);
        }
        el.classList.add('sm-show');
        if (this.capTimer) clearTimeout(this.capTimer);
        if (ms) {
            this.capTimer = setTimeout(() => el.classList.remove('sm-show'), ms);
        }
    }

    private hideCaption(): void {
        if (this.capTimer) clearTimeout(this.capTimer);
        if (this.caption) this.caption.classList.remove('sm-show');
    }

    // ---------------------------------------------------------------------
    // Flight
    // ---------------------------------------------------------------------

    private axes() {
        const cy = Math.cos(this.yaw), sy = Math.sin(this.yaw);
        const cp = Math.cos(this.pitch), sp = Math.sin(this.pitch);
        return {
            fwd: [-cp * sy, sp, cp * cy],
            rgt: [cy, 0, sy],
            up: [-sp * sy, -cp, sp * cy],
        };
    }

    enterFlight(): void {
        if (this.flying) return;
        this.flying = true;
        this.focusIdx = -1;
        const { fwd } = this.axes();
        const D = FOCAL / (0.9 * this.zoom);
        this.cam.x = this.ctr.x - fwd[0] * D;
        this.cam.y = this.ctr.y - fwd[1] * D;
        this.cam.z = this.ctr.z - fwd[2] * D;
        this.vel = { x: 0, y: 0, z: 0 };
        this.targetYaw = this.yaw;
        this.targetPitch = this.pitch;
        try {
            const r = this.canvas.requestPointerLock() as unknown as Promise<void> | undefined;
            if (r && typeof (r as any).catch === 'function') (r as any).catch(() => { });
        } catch { /* a browser that will not lock still flies, just less smoothly */ }
        this.showCaption('flight mode', 'mouse aims · wasd thrust · shift boost · esc to land', 2800);
        this.host.onFlight(true);
    }

    exitFlight(): void {
        if (!this.flying) return;
        this.flying = false;
        const { fwd } = this.axes();
        const D = FOCAL / (0.9 * this.zoom);
        this.ctr.x = this.cam.x + fwd[0] * D;
        this.ctr.y = this.cam.y + fwd[1] * D;
        this.ctr.z = this.cam.z + fwd[2] * D;
        this.vel = { x: 0, y: 0, z: 0 };
        try {
            if (document.pointerLockElement === this.canvas) document.exitPointerLock();
        } catch { /* nothing to unlock */ }
        this.host.onFlight(false);
    }

    flightMode(): boolean {
        return this.flying;
    }

    // ---------------------------------------------------------------------
    // Events
    // ---------------------------------------------------------------------

    private onEnter = () => { this.mouseOver = true; };
    private onLeave = () => { this.mouseOver = false; };

    private rel(e: { clientX: number; clientY: number }) {
        const r = this.canvas.getBoundingClientRect();
        return { x: e.clientX - r.left, y: e.clientY - r.top };
    }

    private hidden(n: StarNode): boolean {
        if (!n.vis || n.near) return true;
        if (this.solo === null) return false;
        // A star with no keyword answers to "(none)", which is what the legend
        // calls that row - so soloing the unkeyworded headings works.
        const mine = this.soloBy === 'status' ? (n.status || '(none)') : n.fam;
        return mine !== this.solo;
    }

    private pick(mx: number, my: number): number {
        let best = -1;
        let bd = 1e9;
        const ns = this.galaxy.nodes;
        for (let i = 0; i < ns.length; i++) {
            const n = ns[i];
            if (this.hidden(n)) continue;
            const dx = n.sx - mx, dy = n.sy - my;
            const d = dx * dx + dy * dy;
            // A floor on the target, because a star three pixels across is not
            // something anybody can be asked to hit.
            const rr = Math.max(n.r * n.ss + 6, 11);
            if (d < rr * rr && d < bd) { bd = d; best = i; }
        }
        return best;
    }

    private onPointerMove = (e: PointerEvent) => {
        const m = this.rel(e);
        if (this.ptrs.has(e.pointerId)) this.ptrs.set(e.pointerId, { x: m.x, y: m.y });
        if (this.ptrs.size === 2) {
            const [a, b] = Array.from(this.ptrs.values());
            const d = Math.hypot(a.x - b.x, a.y - b.y) || 1;
            this.targetZoom = Math.min(ZMAX, Math.max(ZMIN, this.pinchZoom0 * (d / this.pinchStart)));
            this.idleT = 0;
            return;
        }
        if (this.dragging) {
            this.targetYaw -= (m.x - this.px) * 0.005;
            this.targetPitch = Math.max(-1.2, Math.min(1.2, this.targetPitch + (m.y - this.py) * 0.004));
            this.px = m.x; this.py = m.y;
            this.idleT = 0;
            return;
        }
        if (this.flying) {
            this.targetYaw -= (e.movementX || 0) * 0.0024;
            this.targetPitch = Math.max(-1.35, Math.min(1.35, this.targetPitch + (e.movementY || 0) * 0.0019));
            this.hover = -1;
            this.hideTip();
            this.idleT = 0;
            return;
        }
        this.hover = this.pick(m.x, m.y);
        if (this.hover >= 0) {
            const n = this.galaxy.nodes[this.hover];
            if (this.hover !== this.lastBlip) {
                this.host.onConstellation(this.colourFn(n));
                this.lastBlip = this.hover;
            }
            this.showTip(m.x, m.y, n);
            this.canvas.style.cursor = 'pointer';
        } else if (this.hole.scr > 0 && Math.hypot(m.x - this.hole.sx, m.y - this.hole.sy) < this.hole.scr * 1.2) {
            this.showHoleTip(m.x, m.y);
            this.canvas.style.cursor = 'default';
        } else {
            this.hideTip();
            this.canvas.style.cursor = 'grab';
            this.lastBlip = -1;
        }
    };

    private onPointerDown = (e: PointerEvent) => {
        // Right-click never starts a drag: it opens the star's menu.
        if (e.button === 2) { this.dragging = false; return; }
        if (this.tour) this.tourStop();
        try { this.canvas.setPointerCapture(e.pointerId); } catch { /* not capturable */ }
        const m = this.rel(e);
        this.ptrs.set(e.pointerId, { x: m.x, y: m.y });
        if (this.ptrs.size === 2) {
            const [a, b] = Array.from(this.ptrs.values());
            this.pinchStart = Math.hypot(a.x - b.x, a.y - b.y) || 1;
            this.pinchZoom0 = this.targetZoom;
            this.userMoved = true;
            this.dragging = false;
            return;
        }
        this.dragging = true;
        this.px = m.x; this.py = m.y;
        this.downX = m.x; this.downY = m.y;
        this.hideTip();
    };

    private onPointerUp = (e: PointerEvent) => {
        this.ptrs.delete(e.pointerId);
        if (this.ptrs.size > 0) { this.dragging = false; return; }
        this.dragging = false;
        const m = this.rel(e);
        const dx = m.x - this.downX, dy = m.y - this.downY;
        // A click, not the end of a drag.
        if (dx * dx + dy * dy < 25 && !this.flying) {
            const hit = this.pick(m.x, m.y);
            if (hit >= 0) {
                this.host.onOpen(this.galaxy.nodes[hit]);
            } else if (this.focusIdx >= 0) {
                this.clearFocus();
            }
        }
    };

    private onPointerCancel = (e: PointerEvent) => {
        this.ptrs.delete(e.pointerId);
        this.dragging = false;
    };

    private onWheel = (e: WheelEvent) => {
        e.preventDefault();
        this.userMoved = true;
        this.targetZoom = Math.min(ZMAX, Math.max(ZMIN, this.targetZoom * (e.deltaY < 0 ? 1.1 : 0.9)));
    };

    private onPointerLeave = () => {
        this.hover = -1;
        this.hideTip();
    };

    private onDoubleClick = () => {
        this.home();
    };

    private onContextMenu = (e: MouseEvent) => {
        e.preventDefault();
        const m = this.rel(e);
        const hit = this.pick(m.x, m.y);
        if (hit < 0) return;
        this.hideTip();
        this.host.onMenu(this.galaxy.nodes[hit], e.clientX, e.clientY);
    };

    private onKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Escape') {
            if (this.flying) { this.exitFlight(); e.preventDefault(); }
            return;
        }
        // Flight keys only when the pointer is over the map, or already flying -
        // otherwise typing a w into a search box anywhere on the page takes off.
        if (!(this.mouseOver || this.flying)) return;
        const t = e.target as HTMLElement | null;
        if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return;
        const k = e.key.toLowerCase();
        if (k.length === 1 && 'wasdqe'.includes(k)) {
            this.keys.add(k);
            this.enterFlight();
            e.preventDefault();
        }
        if (e.key === 'Shift') this.keys.add('shift');
    };

    private onKeyUp = (e: KeyboardEvent) => {
        this.keys.delete(e.key.toLowerCase());
        if (e.key === 'Shift') this.keys.delete('shift');
    };

    private onLockChange = () => {
        if (this.flying && document.pointerLockElement !== this.canvas) this.exitFlight();
    };

    private bind(): void {
        this.ro = new ResizeObserver(() => this.resize());
        this.ro.observe(this.wrap);
        this.wrap.addEventListener('mouseenter', this.onEnter);
        this.wrap.addEventListener('mouseleave', this.onLeave);
        this.canvas.addEventListener('pointermove', this.onPointerMove);
        this.canvas.addEventListener('pointerdown', this.onPointerDown);
        this.canvas.addEventListener('pointerup', this.onPointerUp);
        this.canvas.addEventListener('pointercancel', this.onPointerCancel);
        this.canvas.addEventListener('pointerleave', this.onPointerLeave);
        this.canvas.addEventListener('wheel', this.onWheel, { passive: false });
        this.canvas.addEventListener('dblclick', this.onDoubleClick);
        this.canvas.addEventListener('contextmenu', this.onContextMenu);
        document.addEventListener('keydown', this.onKeyDown);
        document.addEventListener('keyup', this.onKeyUp);
        document.addEventListener('pointerlockchange', this.onLockChange);
    }

    private unbind(): void {
        this.wrap.removeEventListener('mouseenter', this.onEnter);
        this.wrap.removeEventListener('mouseleave', this.onLeave);
        this.canvas.removeEventListener('pointermove', this.onPointerMove);
        this.canvas.removeEventListener('pointerdown', this.onPointerDown);
        this.canvas.removeEventListener('pointerup', this.onPointerUp);
        this.canvas.removeEventListener('pointercancel', this.onPointerCancel);
        this.canvas.removeEventListener('pointerleave', this.onPointerLeave);
        this.canvas.removeEventListener('wheel', this.onWheel);
        this.canvas.removeEventListener('dblclick', this.onDoubleClick);
        this.canvas.removeEventListener('contextmenu', this.onContextMenu);
        document.removeEventListener('keydown', this.onKeyDown);
        document.removeEventListener('keyup', this.onKeyUp);
        document.removeEventListener('pointerlockchange', this.onLockChange);
    }

    // ---------------------------------------------------------------------
    // The tooltip
    //
    // Written straight into the DOM rather than through React: it moves with the
    // pointer, and a state update per pointermove on a page with four thousand
    // stars in it is a state update per pointermove too many.
    // ---------------------------------------------------------------------

    private placeTip(x: number, y: number): void {
        const el = this.tip as HTMLElement;
        el.style.display = 'block';
        el.style.left = `${Math.min(x + 14, this.W - 330)}px`;
        el.style.top = `${Math.min(y + 12, this.H - 72)}px`;
    }

    private showTip(x: number, y: number, n: StarNode): void {
        if (!this.tip) return;
        const look = this.colourFn(n);
        const fam = lookOf(this.pal, n.fam);
        this.placeTip(x, y);
        this.tip.textContent = '';
        const kind = document.createElement('span');
        kind.className = 'sm-kind';
        kind.style.color = look.css;
        const bits: string[] = [fam.name];
        if (n.status) bits.push(n.status);
        if (n.d) bits.push(n.d + (n.dated ? '' : ' ~'));
        if (n.w) bits.push(`${n.w} in`);
        kind.textContent = bits.join(' · ');
        const name = document.createElement('span');
        name.className = 'sm-name';
        name.textContent = n.label;
        const where = document.createElement('span');
        where.className = 'sm-where';
        where.textContent = n.kind === 'heading' ? `${n.path}:${n.line + 1}` : n.path;
        this.tip.appendChild(kind);
        this.tip.appendChild(name);
        this.tip.appendChild(where);
    }

    private showHoleTip(x: number, y: number): void {
        if (!this.tip) return;
        this.placeTip(x, y);
        this.tip.textContent = '';
        const kind = document.createElement('span');
        kind.className = 'sm-kind';
        kind.style.color = '#F0B34E';
        kind.textContent = 'the black hole';
        const name = document.createElement('span');
        name.className = 'sm-name';
        name.textContent = `${this.hole.n} archived`;
        const where = document.createElement('span');
        where.className = 'sm-where';
        where.textContent = this.hole.eaten.length
            ? this.hole.eaten.slice(0, 4).join(' · ')
            : 'nothing has gone in yet';
        this.tip.appendChild(kind);
        this.tip.appendChild(name);
        this.tip.appendChild(where);
    }

    private hideTip(): void {
        if (this.tip) this.tip.style.display = 'none';
    }

    // ---------------------------------------------------------------------
    // Sprites
    // ---------------------------------------------------------------------

    // A nebula puff: nine offset radial gradients in white, then tinted through
    // source-in. Built once per colour and stamped, because building a gradient
    // per star per frame is what makes fog expensive.
    private puffFor(css: string): HTMLCanvasElement {
        const got = this.puffs.get(css);
        if (got) return got;
        const s = 512;
        const cv = document.createElement('canvas');
        cv.width = cv.height = s;
        const c = cv.getContext('2d') as CanvasRenderingContext2D;
        for (let i = 0; i < 9; i++) {
            const ang = i * 0.72;
            const dist = s * (0.03 + i * 0.012);
            const ox = s / 2 + Math.cos(ang) * dist;
            const oy = s / 2 + Math.sin(ang) * dist;
            const r0 = s * (0.38 + i * 0.015);
            const g = c.createRadialGradient(ox, oy, 0, ox, oy, r0);
            const peak = 0.14 - i * 0.012;
            g.addColorStop(0, `rgba(255,255,255,${Math.max(0.02, peak)})`);
            g.addColorStop(0.3, `rgba(255,255,255,${Math.max(0.01, peak * 0.6)})`);
            g.addColorStop(0.7, `rgba(255,255,255,${Math.max(0.005, peak * 0.15)})`);
            g.addColorStop(1, 'rgba(255,255,255,0)');
            c.fillStyle = g;
            c.fillRect(0, 0, s, s);
        }
        c.globalCompositeOperation = 'source-in';
        c.fillStyle = css;
        c.fillRect(0, 0, s, s);
        this.puffs.set(css, cv);
        return cv;
    }

    private glowFor(css: string): HTMLCanvasElement {
        const got = this.glows.get(css);
        if (got) return got;
        const s = 256;
        const cv = document.createElement('canvas');
        cv.width = cv.height = s;
        const c = cv.getContext('2d') as CanvasRenderingContext2D;
        const g = c.createRadialGradient(s / 2, s / 2, 0, s / 2, s / 2, s / 2);
        g.addColorStop(0, 'rgba(255,255,255,1)');
        g.addColorStop(0.15, 'rgba(255,255,255,0.7)');
        g.addColorStop(0.35, 'rgba(255,255,255,0.3)');
        g.addColorStop(0.6, 'rgba(255,255,255,0.08)');
        g.addColorStop(1, 'rgba(255,255,255,0)');
        c.fillStyle = g;
        c.fillRect(0, 0, s, s);
        c.globalCompositeOperation = 'source-in';
        c.fillStyle = css;
        c.fillRect(0, 0, s, s);
        this.glows.set(css, cv);
        return cv;
    }

    // ---------------------------------------------------------------------
    // The frame
    // ---------------------------------------------------------------------

    private camState(): CameraState {
        return {
            yaw: this.yaw, pitch: this.pitch, zoom: this.zoom,
            flightMode: this.flying, ctr: this.ctr, cam: this.cam,
        };
    }

    private project(p: Projectable): void {
        project(p, this.camState(), this.W, this.H);
    }

    private frame = (now: number) => {
        if (this.dead) return;
        const t = (now - this.t0) / 1000;
        const S = this.S;
        const nodes = this.galaxy.nodes;
        const links = this.galaxy.links;

        // Idle throttling. With the physics frozen and nothing being touched, the
        // galaxy still twinkles and spins, and it can do that at thirty frames a
        // second for half the power. Any interaction restores sixty instantly.
        const isIdle = this.alpha < 0.005 && !this.dragging && !this.flying
            && this.hover < 0 && !this.playing && !this.tour
            && S.warp === 0 && S.heat < 0.01 && this.focusIdx < 0 && this.dying.length === 0;
        this.idleFrames = isIdle ? this.idleFrames + 1 : 0;
        if (this.idleFrames > 60) {
            const skip = this.reduceMotion ? (this.idleFrames % 3 !== 0) : (this.idleFrames % 2 !== 0);
            if (skip) { this.raf = requestAnimationFrame(this.frame); return; }
        }

        if (nodes.length) {
            // Settle then freeze. The galaxy always forms itself while alpha is
            // hot; after that the time warp slider governs, and at its default of
            // zero the simulation stops dead. That is the whole reason a four
            // thousand star database runs smoothly.
            let warp = S.warp;
            if (this.alpha > 0.12) {
                // Shapes form at double speed, because watching a spiral wind up
                // slowly is not the same as watching it wind up.
                warp = Math.max((S.shape || 'natural') !== 'natural' ? 2 : 1, warp);
            } else if (this.reduceMotion) {
                warp = 0;
            } else if (S.heat > 0.01) {
                warp = Math.max(1, warp);
            }
            this.stepAcc += warp;
            // A fixed step, so motion does not depend on the frame rate - but
            // bounded by a time budget, so a big galaxy at a high warp runs
            // slowly instead of not running at all. The backlog is *dropped*
            // rather than carried: carried, it grows every frame and every frame
            // afterwards spends the whole budget catching up with a past it can
            // never reach.
            const until = performance.now() + STEP_BUDGET_MS;
            while (this.stepAcc >= 1) {
                physicsStep(nodes, links, S, this.alpha, this.shapeState);
                this.alpha = coolAlpha(this.alpha, nodes.length);
                this.stepAcc--;
                if (performance.now() > until) { this.stepAcc = 0; break; }
            }

            this.idleT++;
            if (!this.reduceMotion && !this.dragging && !this.flying && this.idleT > 140) {
                this.targetYaw += 0.00035 * S.spin;
            }
            this.yaw += (this.targetYaw - this.yaw) * 0.08;
            this.pitch += (this.targetPitch - this.pitch) * 0.08;
            this.zoom += (this.targetZoom - this.zoom) * 0.08;

            if (this.flying) {
                this.idleT = 0;
                const { fwd, rgt, up } = this.axes();
                const acc = (this.keys.has('shift') ? 0.45 : 0.15) * S.thrust;
                const th = (v: number[], k: number) => {
                    this.vel.x += v[0] * k * acc;
                    this.vel.y += v[1] * k * acc;
                    this.vel.z += v[2] * k * acc;
                };
                if (this.keys.has('w')) th(fwd, 1);
                if (this.keys.has('s')) th(fwd, -1);
                if (this.keys.has('d')) th(rgt, 1);
                if (this.keys.has('a')) th(rgt, -1);
                if (this.keys.has('e')) th(up, 1);
                if (this.keys.has('q')) th(up, -1);
                this.vel.x *= 0.965; this.vel.y *= 0.965; this.vel.z *= 0.965;
                this.cam.x += this.vel.x; this.cam.y += this.vel.y; this.cam.z += this.vel.z;
            } else {
                // Aim at the live centre of the visible stars rather than at the
                // world origin: a settled layout can leave the origin in empty
                // space, and the galaxy then sits in a screen corner with no way
                // to bring it back. This also glides to a soloed constellation
                // and follows the sky as the timeline fills it in.
                const tgt = this.focusIdx >= 0 ? nodes[this.focusIdx] : this.gCtr;
                this.ctr.x += (tgt.x - this.ctr.x) * 0.12;
                this.ctr.y += (tgt.y - this.ctr.y) * 0.12;
                this.ctr.z += (tgt.z - this.ctr.z) * 0.12;
            }

            if (this.tour) {
                this.tour.hold++;
                if (this.tour.hold > (this.reduceMotion ? 90 : 420)) this.tourGo(this.tour.step + 1);
            }
            if (this.playing) {
                this.playAcc++;
                if (this.playAcc >= (this.reduceMotion ? 1 : 14)) {
                    this.playAcc = 0;
                    this.timePos++;
                    const last = this.galaxy.dates.length - 1;
                    if (this.timePos >= last) {
                        this.timePos = Math.max(0, last);
                        this.playing = false;
                    }
                    this.applyTime();
                    this.host.onTime(this.timePos, this.playing);
                }
            }

            for (const n of nodes) { this.project(n); lensPoint(n, this.hole); }
            this.measureExtent();
            // Follow the galaxy out while it is still growing, and stop the moment
            // it settles or the camera is touched. After the projection, because
            // it corrects against what the projection just produced.
            if (!this.userMoved && !this.flying && this.focusIdx < 0
                && (this.alpha > 0.02 || !this.fitted)) {
                this.fitZoom();
                if (this.alpha <= 0.02 && Math.abs(this.targetZoom - this.zoom) < 0.02) {
                    this.fitted = true;
                }
            }
            if (this.ord.length !== nodes.length) this.ord = this.order();
        }

        this.draw(t);

        if (this.wantShot) {
            this.wantShot = false;
            try { this.host.onShot(this.canvas.toDataURL('image/png')); } catch { /* tainted canvas */ }
        }
        this.raf = requestAnimationFrame(this.frame);
    };

    // ---------------------------------------------------------------------
    // Drawing
    // ---------------------------------------------------------------------

    private draw(t: number): void {
        const ctx = this.ctx;
        const S = this.S;
        const W = this.W, H = this.H;
        const nodes = this.galaxy.nodes;
        const links = this.galaxy.links;

        ctx.setTransform(this.DPR, 0, 0, this.DPR, 0, 0);
        const bg = ctx.createRadialGradient(W / 2, H * 0.42, 0, W / 2, H * 0.42, Math.max(W, H) * 0.8);
        bg.addColorStop(0, '#080D1A');
        bg.addColorStop(1, '#03050A');
        ctx.fillStyle = bg;
        ctx.fillRect(0, 0, W, H);

        // The backdrop is real 3D points on a distant sphere, so it turns with
        // everything else. A flat parallax layer slides the wrong way as soon as
        // the camera pitches.
        if (S.stars > 0.02) {
            const sp = scratch();
            for (const s of this.backdrop) {
                sp.x = s.x; sp.y = s.y; sp.z = s.z;
                this.project(sp);
                if (sp.near) continue;
                if (sp.sx < -4 || sp.sx > W + 4 || sp.sy < -4 || sp.sy > H + 4) continue;
                const twk = this.reduceMotion ? 1 : 0.6 + 0.4 * Math.sin(t * 1.1 + s.x * 0.02);
                ctx.fillStyle = `rgba(190,205,235,${Math.min(0.9, 0.12 * s.b * twk * (s.l + 1) * S.stars)})`;
                const px = s.l > 1 ? 1.6 : 1;
                ctx.fillRect(sp.sx, sp.sy, px, px);
            }
        }

        const hn = this.hover >= 0 ? nodes[this.hover] : null;

        // Every hover state eases over about a quarter second rather than
        // snapping, which is the difference between a galaxy responding and a
        // galaxy flashing.
        for (let i = 0; i < nodes.length; i++) {
            const n = nodes[i];
            const dimTarget = hn && i !== this.hover && !hn.nbr.has(i) ? 1 : 0;
            n.dim = (n.dim || 0) + (dimTarget - (n.dim || 0)) * 0.09;
            const litTarget = (i === this.hover || i === this.focusIdx) ? 1 : 0;
            n.litE = (n.litE || 0) + (litTarget - (n.litE || 0)) * 0.15;
        }
        for (const l of links) {
            const on = hn && (l.s === this.hover || l.t === this.hover) ? 1 : 0;
            l.hl = (l.hl || 0) + (on - (l.hl || 0)) * 0.12;
            l.dm = (l.dm || 0) + ((hn && !on ? 1 : 0) - (l.dm || 0)) * 0.09;
        }
        for (const k in this.famF) {
            this.famF[k] += ((hn && hn.fam !== k ? 1 : 0) - this.famF[k]) * 0.09;
        }

        this.drawNebula(t);
        this.drawCartography(t);
        this.drawMeteor();
        this.drawHole(t);
        this.drawThreads();
        this.drawParticles();
        this.drawStars(t);
        this.drawStarNames(t);
        this.drawLabels();
    }

    private famFade0(k: string): number {
        return this.famF[k] === undefined ? 0 : this.famF[k];
    }

    // Nebula fog: puffs stamped round each hub, at 70% resolution and screened
    // back on.
    private drawNebula(t: number): void {
        const S = this.S;
        if (S.nebula <= 0.02) return;
        const fog = this.fogCtx;
        const W = this.W, H = this.H;
        fog.setTransform(1, 0, 0, 1, 0, 0);
        fog.clearRect(0, 0, this.fogCv.width, this.fogCv.height);
        fog.setTransform(0.7, 0, 0, 0.7, 0, 0);
        fog.globalCompositeOperation = 'lighter';
        const anchors = this.galaxy.anchors;
        for (let ai = 0; ai < anchors.length; ai++) {
            const n = anchors[ai];
            if (this.hidden(n)) continue;
            const look = this.colourFn(n);
            const sprite = this.puffFor(look.css);
            const fd = this.famFade0(n.fam);
            const baseR = Math.min(420, (62 + n.w * 5.5) * n.ss);
            const ext = baseR * 2.4;
            if (n.sx < -ext || n.sx > W + ext || n.sy < -ext || n.sy > H + ext) continue;
            const puffN = n.ss > 1.8 ? 8 : (n.w >= 10 ? 16 : 12);
            for (let p = 0; p < puffN; p++) {
                const h1 = hash(ai, p), h2 = hash(ai, p + 50), h3 = hash(ai, p + 100);
                const ang = h1 * 6.283 + (this.reduceMotion ? 0 : t * 0.03 * (h2 - 0.5));
                const dist = baseR * (0.15 + h2 * 0.75);
                const R = baseR * (0.55 + h3 * 0.9);
                const a = (0.09 - 0.04 * fd) * S.nebula
                    * (0.6 + 0.4 * Math.sin(t * 0.2 + h1 * 6.283))
                    * (n.nf === undefined ? 1 : n.nf);
                if (a < 0.009) continue;
                fog.globalAlpha = Math.max(0.008, a);
                fog.drawImage(sprite, n.sx + Math.cos(ang) * dist - R, n.sy + Math.sin(ang) * dist - R, R * 2, R * 2);
            }
            if (fd < 0.9 && S.dust > 0.02) {
                fog.fillStyle = `rgba(${look.rgb},0.5)`;
                for (let d = 0; d < 18; d++) {
                    const h1 = hash(ai + 300, d), h2 = hash(ai + 400, d);
                    const ang = h1 * 6.283;
                    const dist = baseR * (0.2 + h2 * 0.9);
                    const twk = this.reduceMotion ? 0.5 : 0.25 + 0.45 * Math.sin(t * 1.6 + h1 * 40);
                    fog.globalAlpha = Math.min(0.9, 0.35 * twk * (1 - fd) * S.dust);
                    fog.fillRect(n.sx + Math.cos(ang) * dist, n.sy + Math.sin(ang) * dist, 2.6, 2.6);
                }
            }
        }
        fog.globalAlpha = 1;
        const ctx = this.ctx;
        ctx.globalCompositeOperation = 'screen';
        ctx.drawImage(this.fogCv, 0, 0, W, H);
        ctx.globalCompositeOperation = 'source-over';
    }

    // Constellation boundaries, and their names on tilted orbital rings.
    //
    // This is also where the galaxy's live centre and radius are measured, and
    // where the black hole is given its bearing - all three are sums over the
    // visible stars and doing them twice would be doing them twice.
    private drawCartography(t: number): void {
        const ctx = this.ctx;
        const S = this.S;
        const nodes = this.galaxy.nodes;

        const famPts: Record<string, number[][]> = {};
        const famNds: Record<string, StarNode[]> = {};
        let gcx = 0, gcy = 0, gcz = 0, gn = 0;
        for (const n of nodes) {
            if (this.hidden(n)) continue;
            (famPts[n.fam] = famPts[n.fam] || []).push([n.sx, n.sy]);
            (famNds[n.fam] = famNds[n.fam] || []).push(n);
            gcx += n.x; gcy += n.y; gcz += n.z; gn++;
        }
        if (gn) {
            gcx /= gn; gcy /= gn; gcz /= gn;
            this.gCtr = { x: gcx, y: gcy, z: gcz };
        }
        // The radius at the 85th percentile rather than the maximum: one star
        // flung out by a shape change must not push every name out with it.
        const gdist: number[] = [];
        for (const n of nodes) {
            if (this.hidden(n)) continue;
            gdist.push(Math.hypot(n.x - gcx, n.y - gcy, n.z - gcz));
        }
        gdist.sort((a, b) => a - b);
        const Rg = gdist[Math.floor(gdist.length * 0.85)] || 100;

        const gP = scratch();
        gP.x = gcx; gP.y = gcy; gP.z = gcz;
        this.project(gP);

        // The hole rides a fixed bearing off the rim and follows the galaxy as it
        // breathes, eased - so settling and growth never make it jump.
        this.hole.tx = gcx + Math.cos(2.1) * Rg * 1.8;
        this.hole.ty = gcy + Rg * 0.34;
        this.hole.tz = gcz + Math.sin(2.1) * Rg * 1.8;
        this.hole.rg = Rg;
        if (!this.hole.init) {
            this.hole.x = this.hole.tx; this.hole.y = this.hole.ty; this.hole.z = this.hole.tz;
            this.hole.init = true;
        }

        const famOrder = this.galaxy.families.map(f => f.key);
        for (const key in famPts) {
            const pts = famPts[key];
            if (pts.length < 4) continue;
            const fd = this.famFade0(key);
            const look = lookOf(this.pal, key);
            const h = hull(pts);
            if (!h || h.length < 3) continue;

            let cx = 0, cy = 0;
            for (const p of h) { cx += p[0]; cy += p[1]; }
            cx /= h.length; cy /= h.length;
            ctx.setLineDash([2, 6]);
            ctx.strokeStyle = `rgba(${look.rgb},${0.13 - 0.08 * fd})`;
            ctx.lineWidth = 0.8;
            ctx.beginPath();
            h.forEach((p, i) => {
                // Pushed out a little from the centre, so the boundary sits
                // around the stars rather than through the outermost ones.
                const ix = p[0] + (p[0] - cx) * 0.14;
                const iy = p[1] + (p[1] - cy) * 0.14;
                if (i) ctx.lineTo(ix, iy); else ctx.moveTo(ix, iy);
            });
            ctx.closePath();
            ctx.stroke();
            ctx.setLineDash([]);

            if (S.names < 0.02) continue;
            this.drawRingName(key, famNds[key] || [], famOrder, gcx, gcy, gcz, Rg, gP, fd, look);
        }
    }

    // One constellation's name, on its own tilted ring around the whole galaxy.
    //
    // Everything difficult here is about a name never blinking. It lives in world
    // space at its constellation's bearing and wheels with the rotation, so over a
    // full turn it goes edge on, upside down and round the back - and at each of
    // those it has to melt out and back rather than flicking. Hence: a crowding
    // test for the whole name at once (never per letter, or the letters pile up), a
    // latched flip that only changes while the name is invisible, a tilt fade, a
    // sticky on/off with a dwell, and an eased alpha on top of all of it.
    private drawRingName(
        key: string,
        members: StarNode[],
        famOrder: string[],
        gcx: number, gcy: number, gcz: number,
        Rg: number,
        gP: Projectable,
        fd: number,
        look: FamilyLook,
    ): void {
        if (members.length < 4) return;
        const ctx = this.ctx;
        const S = this.S;

        // The constellation's own centre, weighted by how linked each star is, so
        // the name sits over the busy part of it.
        let c3x = 0, c3y = 0, c3z = 0, twt = 0;
        for (const n of members) {
            const wgt = 1 + n.w;
            c3x += n.x * wgt; c3y += n.y * wgt; c3z += n.z * wgt; twt += wgt;
        }
        c3x /= twt; c3y /= twt; c3z /= twt;

        const idxF = Math.max(0, famOrder.indexOf(key));
        const inc = ((idxF % 7) - 3) * 0.20;   // this ring's tilt out of the plane
        const nodA = idxF * 2.399;             // where its tilt axis points
        const ux = Math.cos(nodA), uz = Math.sin(nodA);
        const vx = -Math.sin(nodA) * Math.cos(inc), vy = Math.sin(inc), vz = Math.cos(nodA) * Math.cos(inc);
        // Each ring a little wider than the last, tightening as constellations
        // multiply so the outermost still stays near home.
        const R3 = Rg * 1.24 + 20 + idxF * Math.min(9, 63 / Math.max(7, famOrder.length - 1));
        const scRef = gP.ss;
        const fs = Math.max(9, Math.min(30, Rg * scRef * 0.115)) * S.nameSize;
        if (fs <= 9.5) return;

        const rname = look.name.toUpperCase();
        if (!this.famLC[rname]) {
            ctx.font = 'italic 100px Georgia, serif';
            const adv: number[] = [];
            let tot = 0;
            for (const chr of rname) {
                const w = ctx.measureText(chr).width;
                adv.push(w);
                tot += w;
            }
            this.famLC[rname] = { adv, tot };
        }
        const lc = this.famLC[rname];
        const sc = fs / 100;

        // The point on this ring nearest the constellation's stars. A fixed
        // anchor, so the name does not crawl along its ring as the galaxy breathes.
        let angW = 0, bD = Infinity;
        for (let s = 0; s < 64; s++) {
            const a = s / 64 * 6.28319;
            const px = gcx + (ux * Math.cos(a) + vx * Math.sin(a)) * R3;
            const py = gcy + (vy * Math.sin(a)) * R3;
            const pz = gcz + (uz * Math.cos(a) + vz * Math.sin(a)) * R3;
            const d2 = (px - c3x) ** 2 + (py - c3y) ** 2 + (pz - c3z) ** 2;
            if (d2 < bD) { bD = d2; angW = a; }
        }

        const spacing = fs * 0.14;
        const totalAng = (lc.tot * sc + spacing * (rname.length - 1)) / (R3 * scRef);

        const at = (a: number): Projectable => {
            const o = scratch();
            o.x = gcx + (ux * Math.cos(a) + vx * Math.sin(a)) * R3;
            o.y = gcy + (vy * Math.sin(a)) * R3;
            o.z = gcz + (uz * Math.cos(a) + vz * Math.sin(a)) * R3;
            this.project(o);
            return o;
        };
        const cwS = at(angW - totalAng / 2);
        const cwM = at(angW);
        const cwE = at(angW + totalAng / 2);

        // Crowding, for the whole name at once: how much screen each half of the
        // arc gives the letters against how much they need. An edge-on ring gives
        // them less, so the whole name fades as one unit - no half words, no
        // letters stacked on each other.
        const relM = Math.max(0.35, Math.min(1.6, cwM.ss / Math.max(0.001, scRef)));
        const halfW = Math.max(1, (lc.tot * sc + spacing * (rname.length - 1)) * 0.5 * relM);
        const c1 = Math.hypot(cwM.sx - cwS.sx, cwM.sy - cwS.sy) / halfW;
        const c2 = Math.hypot(cwE.sx - cwM.sx, cwE.sy - cwM.sy) / halfW;
        const crowd = Math.min(c1, c2);
        const crowdFade = Math.min(1, Math.max(0, (crowd - 0.40) / 0.25));

        // How deep behind the galaxy's centre the name sits, as a fraction of its
        // ring: it melts away as it swings round the back of the ball.
        const depthFrac = (cwM.sd - gP.sd) / R3;
        const depthFade = Math.min(1, Math.max(0, (0.10 - depthFrac) / 0.55));

        // The latched flip. `wantFlip` is which way it should read now, with a few
        // pixels of hysteresis so it cannot dither near vertical; the stored flip
        // only adopts it once the name has fully melted out, so the 180° twist
        // happens off stage.
        const eDx = cwE.sx - cwS.sx;
        if (this.famFlip[key] === undefined) this.famFlip[key] = eDx < 0;
        const wantFlip = Math.abs(eDx) < 4 ? this.famFlip[key] : (eDx < 0);
        const fPrev0 = this.famFade[key];
        if (this.famFlip[key] !== wantFlip && (fPrev0 === undefined || fPrev0 < 0.03)) {
            this.famFlip[key] = wantFlip;
        }
        const flip = this.famFlip[key];

        // Tilt: a name melts out as it keels past about 40° and is gone by 65°, so
        // you never watch the letters rotate towards vertical.
        const eDy = cwE.sy - cwS.sy;
        let tilt = Math.abs(Math.atan2(eDy, eDx)) * 57.2958;
        if (tilt > 90) tilt = 180 - tilt;
        const tiltFade = Math.min(1, Math.max(0, (65 - tilt) / 25));

        // One clean vanish and one clean return per transit. Once out, a name stays
        // out for ninety frames and can only relight on a strong case, so the faint
        // mid-transit blips can never bring it back; while lit it may dim but not
        // below a floor, so a brief squeeze reads as a dip rather than a blink.
        let vTgt = crowdFade * depthFade * tiltFade;
        let onSt = this.famOn[key] === true;
        let offAge = (this.famOffAge[key] === undefined ? 999 : this.famOffAge[key]) + 1;
        if (!onSt && vTgt > 0.55 && offAge > 90) onSt = true;
        else if (onSt && vTgt < 0.08) { onSt = false; offAge = 0; }
        this.famOn[key] = onSt;
        this.famOffAge[key] = offAge;
        vTgt = onSt ? Math.max(vTgt, 0.25) : 0;

        const fTgt = (flip === wantFlip) ? vTgt : 0;
        const fPrev = fPrev0 === undefined ? fTgt : fPrev0;
        const fEase = this.famFade[key] = fPrev + (fTgt - fPrev) * 0.08;
        const gnf = gP.nf === undefined ? 1 : gP.nf;
        const baseA = (0.34 - 0.24 * fd) * fEase * gnf;
        if (baseA <= 0.01) return;

        ctx.textAlign = 'center';
        let a = angW - totalAng / 2;
        for (let ci = 0; ci < rname.length; ci++) {
            const li = flip ? rname.length - 1 - ci : ci;
            const da = (lc.adv[li] * sc / 2) / (R3 * scRef);
            a += da;
            const tmp = at(a);
            if (!tmp.near) {
                // Where the next bit of arc goes, which is the letter's rotation.
                const tt = at(a + 0.02);
                const rot = Math.atan2(tt.sy - tmp.sy, tt.sx - tmp.sx);
                const rel = Math.max(0.35, Math.min(1.6, tmp.ss / Math.max(0.001, scRef)));
                const aL = baseA * (tmp.nf === undefined ? 1 : tmp.nf);
                if (aL > 0.02) {
                    ctx.save();
                    ctx.translate(tmp.sx, tmp.sy);
                    ctx.rotate(flip ? rot + Math.PI : rot);
                    ctx.font = `italic ${(fs * rel).toFixed(1)}px Georgia, serif`;
                    ctx.fillStyle = `rgba(${look.rgb},${aL.toFixed(3)})`;
                    ctx.fillText(rname[li], 0, 0);
                    ctx.restore();
                }
            }
            a += da + spacing / (R3 * scRef);
        }
    }

    private drawMeteor(): void {
        if (this.reduceMotion) return;
        const ctx = this.ctx;
        const S = this.S;
        if (this.shoot) {
            this.shoot.t += 0.03;
            if (this.shoot.t > 1) { this.shoot = null; return; }
            const s = this.shoot;
            const sx = s.x + s.dx * s.t, sy = s.y + s.dy * s.t;
            const g = ctx.createLinearGradient(sx, sy, sx - s.dx * 0.12, sy - s.dy * 0.12);
            g.addColorStop(0, 'rgba(220,240,255,0.9)');
            g.addColorStop(1, 'rgba(220,240,255,0)');
            ctx.strokeStyle = g;
            ctx.lineWidth = 1.4;
            ctx.beginPath();
            ctx.moveTo(sx, sy);
            ctx.lineTo(sx - s.dx * 0.12, sy - s.dy * 0.12);
            ctx.stroke();
            return;
        }
        if (S.meteors > 0.01 && --this.shootTimer <= 0) {
            const now = performance.now() | 0;
            this.shootTimer = Math.max(20, (1600 + (now % 1400)) / S.meteors);
            const fromLeft = (now % 2) === 0;
            this.shoot = {
                x: fromLeft ? -50 : this.W + 50,
                y: this.H * 0.12 + (now % Math.max(1, this.H * 0.45 | 0)),
                dx: (fromLeft ? 1 : -1) * (this.W * 0.5),
                dy: this.H * 0.22,
                t: 0,
            };
        }
    }

    // The black hole, and the stars falling into it.
    //
    // Drawn before the threads and the stars, so those pass in front of it. Its own
    // light is additive, which makes it order-independent and so unable to flicker
    // however the galaxy crosses it. It exerts no force on anything: the layout
    // cannot be disturbed by decoration.
    private drawHole(t: number): void {
        const ctx = this.ctx;
        const S = this.S;
        const hole = this.hole;
        hole.scr = 0;
        hole.lens = 0;
        if (S.hole <= 0.02 || !this.galaxy.nodes.length || !hole.init) return;

        hole.x += (hole.tx - hole.x) * 0.04;
        hole.y += (hole.ty - hole.y) * 0.04;
        hole.z += (hole.tz - hole.z) * 0.04;
        this.project(hole);

        // Far-side fade, the same trick the constellation names use: when its
        // orbit carries it behind the galaxy the whole object melts out rather
        // than punching a black disc through the bright core.
        const rg = hole.rg || 100;
        const far = Math.min(1, Math.max(0, (hole.sd - rg * 0.5) / rg));
        const hnf = (hole.nf === undefined ? 1 : hole.nf) * (1 - far);

        if (!hole.near && hnf > 0.02) {
            const depth = Math.max(0.25, Math.min(1.15, 1 - hole.sd / 500));
            // The horizon grows with every meal, on a square root, so a hundred
            // archived headings and a thousand differ visibly without the second
            // one filling the screen.
            const R0 = Math.min(96, (17 + Math.min(30, Math.sqrt(hole.n || 0) * 3.4)) * S.hole * hole.ss);
            if (hole.sx > -R0 * 4 && hole.sx < this.W + R0 * 4 && hole.sy > -R0 * 4 && hole.sy < this.H + R0 * 4) {
                hole.scr = R0;
                hole.lens = R0 * 1.35 * hnf;
                if (hole.lens > 8) this.drawLensing(R0);
                this.drawDisk(R0, hnf, depth, t);
            }
        }

        // The stars that have left the database, spiralling in.
        for (let di = this.dying.length - 1; di >= 0; di--) {
            const dn = this.dying[di];
            dn.t += this.reduceMotion ? 0.05 : DYING_RATE;
            if (dn.t >= 1) { this.dying.splice(di, 1); continue; }
            const p = dn.t * dn.t * (3 - 2 * dn.t);   // smoothstep, so no pops
            const swirl = (1 - p) * 46;
            const an = dn.ph + p * 9.5;
            const wp = scratch();
            wp.x = dn.x + (hole.x - dn.x) * p + Math.cos(an) * swirl;
            wp.y = dn.y + (hole.y - dn.y) * p + Math.sin(an) * swirl * 0.4;
            wp.z = dn.z + (hole.z - dn.z) * p + Math.sin(an) * swirl;
            this.project(wp);
            if (wp.near) continue;
            const fa = (1 - p * 0.6) * (wp.nf === undefined ? 1 : wp.nf);
            ctx.fillStyle = `rgba(${lookOf(this.pal, dn.fam).rgb},${(0.9 * fa).toFixed(3)})`;
            ctx.beginPath();
            ctx.arc(wp.sx, wp.sy, Math.max(0.8, dn.r * wp.ss * (1 - p * 0.8)), 0, 7);
            ctx.fill();
        }
    }

    // Pixel lensing: re-draw the sky that has already been painted around the
    // hole, pulled toward the horizon ring by ring, so fog, glow and starfield
    // visibly bend. Inside the Einstein ring the sky reappears inverted - the
    // secondary image.
    private drawLensing(R0: number): void {
        const ctx = this.ctx;
        const hole = this.hole;
        const thE = hole.lens as number;
        const DPR = this.DPR;
        const LR = Math.ceil(Math.min(1000, Math.max(this.W, this.H), R0 * 7) / 16) * 16;

        if (!this.warpCv) {
            this.warpCv = document.createElement('canvas');
            this.warpCtx = this.warpCv.getContext('2d');
            this.warp2 = document.createElement('canvas');
            this.warp2Ctx = this.warp2.getContext('2d');
        }
        const wcv = this.warpCv as HTMLCanvasElement;
        const wc = this.warpCtx as CanvasRenderingContext2D;
        const w2 = this.warp2 as HTMLCanvasElement;
        const w2c = this.warp2Ctx as CanvasRenderingContext2D;

        const side = Math.min(2048, Math.ceil(LR * 2 * DPR / 64) * 64);
        if (wcv.width !== side) { wcv.width = side; wcv.height = side; }
        if (w2.width !== LR * 2) { w2.width = LR * 2; w2.height = LR * 2; }

        const cx0 = hole.sx - LR, cy0 = hole.sy - LR;
        const qx0 = Math.max(0, cx0), qy0 = Math.max(0, cy0);
        const qx1 = Math.min(this.W, hole.sx + LR), qy1 = Math.min(this.H, hole.sy + LR);
        if (qx1 <= qx0 || qy1 <= qy0) return;

        wc.clearRect(0, 0, side, side);
        wc.drawImage(
            this.canvas,
            qx0 * DPR, qy0 * DPR, (qx1 - qx0) * DPR, (qy1 - qy0) * DPR,
            (qx0 - cx0) * DPR, (qy0 - cy0) * DPR, (qx1 - qx0) * DPR, (qy1 - qy0) * DPR,
        );

        // Fine annular slices, densest at the ring where the deflection changes
        // fastest, then composited back through a 1px blur which fuses the steps
        // and reads as gravitational heat haze.
        const NR = R0 > 40 ? 96 : R0 > 20 ? 64 : 32;
        const inR = thE * 1.02;
        const sw = LR * 2 * DPR;
        const rg = (x: number) => inR + (LR - inR) * Math.pow(x, 1.7);
        w2c.clearRect(0, 0, LR * 2, LR * 2);
        for (let ri = 0; ri < NR; ri++) {
            const r0 = rg(ri / NR);
            const r1 = rg((ri + 1) / NR) + 0.7;   // overlap, which hides the seams
            const m = (r0 + r1) / 2;
            let defl = thE * thE / m;
            // Tapered to nothing at the rim, or the outermost slice leaves a seam.
            defl *= Math.max(0, 1 - Math.pow((m - inR) / (LR - inR), 2));
            // Capped, or a slice near the ring explodes into a radial smear.
            const inv = Math.min(2.2, m / Math.max(1, m - defl));
            w2c.save();
            w2c.beginPath();
            w2c.arc(LR, LR, r1, 0, 7);
            w2c.arc(LR, LR, r0, 0, 7, true);
            w2c.clip();
            w2c.translate(LR, LR);
            w2c.scale(inv, inv);
            w2c.drawImage(wcv, 0, 0, sw, sw, -LR, -LR, LR * 2, LR * 2);
            w2c.restore();
        }
        // The secondary image: the sky inside the ring, inverted and squeezed.
        w2c.save();
        w2c.beginPath();
        w2c.arc(LR, LR, inR + 0.6, 0, 7);
        w2c.clip();
        w2c.translate(LR, LR);
        w2c.rotate(Math.PI);
        w2c.scale(0.45, 0.45);
        w2c.globalAlpha = 0.85;
        w2c.drawImage(wcv, 0, 0, sw, sw, -LR, -LR, LR * 2, LR * 2);
        w2c.restore();

        ctx.save();
        ctx.globalAlpha = 1;
        ctx.globalCompositeOperation = 'source-over';
        ctx.beginPath();
        ctx.arc(hole.sx, hole.sy, LR - 2, 0, 7);
        ctx.clip();
        try { ctx.filter = 'blur(1px)'; } catch { /* not every browser has it */ }
        ctx.drawImage(w2, 0, 0, LR * 2, LR * 2, hole.sx - LR, hole.sy - LR, LR * 2, LR * 2);
        try { ctx.filter = 'none'; } catch { /* nothing to reset */ }
        ctx.restore();
    }

    // The accretion disk, the lensed ring over the crown, and the horizon.
    //
    // Near edge on, crossing in front of and behind the sphere, with the far side's
    // light bent over the top as a full ring and the approaching side burning
    // brighter. Gargantua, not Saturn.
    private drawDisk(R0: number, hnf: number, depth: number, t: number): void {
        const ctx = this.ctx;
        const hole = this.hole;
        const S = this.S;
        // The gold follows the universe hue, so a rotated sky does not leave one
        // gold object in it.
        const rot = (hex: string, rgb: string) => {
            if (!S.hue) return rgb;
            // Imported lazily through the palette's own helper would be circular;
            // the arithmetic is small and local.
            const r = parseInt(hex.slice(1, 3), 16), g = parseInt(hex.slice(3, 5), 16), b = parseInt(hex.slice(5, 7), 16);
            const mx = Math.max(r, g, b) / 255, mn = Math.min(r, g, b) / 255;
            const l = (mx + mn) / 2;
            let h = 0, s = 0;
            if (mx !== mn) {
                const d = mx - mn;
                s = l > 0.5 ? d / (2 - mx - mn) : d / (mx + mn);
                const rr = r / 255, gg = g / 255, bb = b / 255;
                h = mx === rr ? (gg - bb) / d + (gg < bb ? 6 : 0) : mx === gg ? (bb - rr) / d + 2 : (rr - gg) / d + 4;
                h /= 6;
            }
            h = (h + S.hue / 360) % 1;
            const q = l < 0.5 ? l * (1 + s) : l + s - l * s;
            const p = 2 * l - q;
            const f = (x: number) => {
                x = (x % 1 + 1) % 1;
                return x < 1 / 6 ? p + (q - p) * 6 * x : x < 0.5 ? q : x < 2 / 3 ? p + (q - p) * (2 / 3 - x) * 6 : p;
            };
            return `${Math.round(f(h + 1 / 3) * 255)},${Math.round(f(h) * 255)},${Math.round(f(h - 1 / 3) * 255)}`;
        };
        const AC = rot('#F0B34E', '240,179,78');    // the disk's gold
        const HOT = rot('#FFE9C4', '255,233,196');  // the white heat at its inner edge
        const ph = this.reduceMotion ? 0 : t * 0.35;
        const TILT = 0.42;
        const A = hnf * depth;

        ctx.save();
        ctx.translate(hole.sx, hole.sy);
        ctx.globalCompositeOperation = 'screen';

        // A tight ambient glow. Mood, not a floodlight.
        const g = ctx.createRadialGradient(0, 0, R0 * 0.8, 0, 0, R0 * 2.6);
        g.addColorStop(0, `rgba(${AC},0)`);
        g.addColorStop(0.25, `rgba(${AC},${(0.16 * A).toFixed(3)})`);
        g.addColorStop(1, `rgba(${AC},0)`);
        ctx.fillStyle = g;
        ctx.fillRect(-R0 * 2.7, -R0 * 2.7, R0 * 5.4, R0 * 5.4);

        ctx.rotate(TILT);
        // The lensed ring: the far side of the disk bent around the sphere. Drawn
        // as exact butt-capped segments rather than one arc, because overlapping
        // strokes under additive blending stamp a bright tick at every joint.
        const SEG = R0 > 30 ? 60 : R0 > 15 ? 36 : 20;
        const TAU = 6.28319;
        for (let si = 0; si < SEG; si++) {
            const a0 = (si / SEG) * TAU, a1 = ((si + 1) / SEG) * TAU;
            const am = (a0 + a1) / 2;
            const dopp = Math.max(0.10, 0.4 + 0.6 * Math.cos(am));      // approaching side burns
            const topBias = 0.7 + 0.3 * Math.max(0, -Math.sin(am));     // crown over chin
            const shim = 1 + 0.10 * Math.sin(am * 3 - ph * 4);
            const rr = R0 * 1.10;
            ctx.strokeStyle = `rgba(${HOT},${Math.min(1, 1.1 * A * dopp * topBias * shim).toFixed(3)})`;
            ctx.lineWidth = Math.max(1.1, R0 * 0.045);
            ctx.beginPath(); ctx.arc(0, 0, rr, a0, a1); ctx.stroke();
            ctx.strokeStyle = `rgba(${AC},${(0.20 * A * dopp * topBias).toFixed(3)})`;
            ctx.lineWidth = Math.max(1.8, R0 * 0.08);
            ctx.beginPath(); ctx.arc(0, 0, rr * 1.035, a0, a1); ctx.stroke();
        }
        // Lensed again under the chin: a fainter, tighter mirror arc.
        ctx.strokeStyle = `rgba(${HOT},${(0.32 * A).toFixed(3)})`;
        ctx.lineWidth = Math.max(0.8, R0 * 0.028);
        ctx.beginPath(); ctx.arc(0, 0, R0 * 1.22, 0.55, 2.6); ctx.stroke();
        ctx.strokeStyle = `rgba(${AC},${(0.12 * A).toFixed(3)})`;
        ctx.lineWidth = Math.max(1.4, R0 * 0.05);
        ctx.beginPath(); ctx.arc(0, 0, R0 * 1.26, 0.55, 2.6); ctx.stroke();

        // The disk itself, as a closed squashed annulus in two halves: the back
        // half first so the horizon then hides what passes behind it, the front
        // half after so it crosses in front.
        const diskHalf = (a0: number, a1: number, mul: number) => {
            ctx.save();
            ctx.scale(1, 0.13);
            ctx.beginPath();
            ctx.arc(0, 0, R0 * 3.3, a0, a1);
            ctx.arc(0, 0, R0 * 1.05, a1, a0, true);
            ctx.closePath();
            ctx.clip();
            ctx.globalAlpha = mul;
            const bb = ctx.createRadialGradient(0, 0, R0 * 1.05, 0, 0, R0 * 3.3);
            const stops: [number, string, number][] = [
                [0.00, HOT, Math.min(1, 0.95 * A)],
                [0.09, HOT, 0.55 * A],
                [0.13, AC, 0.18 * A],
                [0.18, AC, 0.60 * A],
                [0.30, AC, 0.48 * A],
                [0.34, AC, 0.14 * A],
                [0.40, AC, 0.46 * A],
                [0.55, AC, 0.28 * A],
                [0.60, AC, 0.09 * A],
                [0.66, AC, 0.24 * A],
                [0.82, AC, 0.10 * A],
            ];
            for (const [at, col, al] of stops) bb.addColorStop(at, `rgba(${col},${al.toFixed(3)})`);
            bb.addColorStop(1, `rgba(${AC},0)`);
            ctx.fillStyle = bb;
            ctx.fillRect(-R0 * 3.4, -R0 * 3.4, R0 * 6.8, R0 * 6.8);
            if (mul >= 1) {
                // The doppler burn on the approaching wing, kept inside the ring.
                const db = ctx.createRadialGradient(R0 * 1.6, R0 * 0.3, 0, R0 * 1.6, R0 * 0.3, R0 * 1.4);
                db.addColorStop(0, `rgba(${HOT},${Math.min(1, 0.85 * A).toFixed(3)})`);
                db.addColorStop(0.45, `rgba(${HOT},${(0.28 * A).toFixed(3)})`);
                db.addColorStop(1, `rgba(${HOT},0)`);
                ctx.fillStyle = db;
                ctx.fillRect(-R0 * 3.4, -R0 * 3.4, R0 * 6.8, R0 * 6.8);
            }
            ctx.globalAlpha = 1;
            ctx.restore();
        };
        diskHalf(Math.PI, TAU, 0.5);

        ctx.globalCompositeOperation = 'source-over';
        // The horizon: a soft-edged void rather than a flat coin.
        const hg = ctx.createRadialGradient(0, 0, 0, 0, 0, R0);
        hg.addColorStop(0, `rgba(0,0,0,${hnf.toFixed(3)})`);
        hg.addColorStop(0.86, `rgba(0,0,0,${hnf.toFixed(3)})`);
        hg.addColorStop(1, 'rgba(0,0,0,0)');
        ctx.fillStyle = hg;
        ctx.beginPath(); ctx.arc(0, 0, R0, 0, 7); ctx.fill();

        ctx.globalCompositeOperation = 'screen';
        // The photon ring, razor thin at the horizon's edge.
        ctx.strokeStyle = `rgba(${HOT},${(0.9 * A).toFixed(3)})`;
        ctx.lineWidth = 1.3;
        ctx.beginPath(); ctx.arc(0, 0, R0 * 1.02, 0, 7); ctx.stroke();
        ctx.strokeStyle = `rgba(${HOT},${(0.25 * A).toFixed(3)})`;
        ctx.lineWidth = 3.5;
        ctx.beginPath(); ctx.arc(0, 0, R0 * 1.05, 0, 7); ctx.stroke();

        diskHalf(0, Math.PI, 1);
        ctx.globalCompositeOperation = 'source-over';
        ctx.restore();
    }

    // The threads. Links between two stars of one constellation take its colour,
    // a link across constellations is grey, and an outline edge is fainter than
    // either - there is one of them per heading, and at a link's brightness the
    // galaxy is a ball of wool.
    private drawThreads(): void {
        const ctx = this.ctx;
        const S = this.S;
        const nodes = this.galaxy.nodes;
        const hn = this.hover >= 0 ? nodes[this.hover] : null;
        const shaped = (S.shape || 'natural') !== 'natural';
        const shpNow = S.shape || 'natural';
        const mp = scratch();

        for (const l of this.galaxy.links) {
            const a = nodes[l.s], b = nodes[l.t];
            if (!a || !b) continue;
            if (this.hidden(a) || this.hidden(b)) continue;
            const outline = l.kind === 'outline';
            const slider = outline ? S.outlineAlpha : S.linkAlpha;
            if (slider <= 0 && (l.hl || 0) < 0.05) continue;
            const depth = Math.max(0.15, Math.min(1, 1 - ((a.sd + b.sd) / 2) / 420));
            const la = Math.min(1, slider);
            const sameFam = a.fam === b.fam;
            const col = (l.hl !== undefined && l.hl > 0.05 && hn)
                ? this.colourFn(hn).rgb
                : (sameFam ? this.colourFn(a).rgb : '120,140,185');
            const baseA = Math.min(0.9, (sameFam ? 0.24 : 0.10) * depth * slider);
            const nf = Math.min(a.nf === undefined ? 1 : a.nf, b.nf === undefined ? 1 : b.nf);
            let alpha = (baseA * (1 - 0.82 * (l.dm || 0)) + 0.30 * la * (l.hl || 0)) * nf;
            let shF = 1;
            if (shaped) {
                // With a shape on, a thread stretched across the whole picture
                // fades out: those were the tangle. Hovering still lights its own.
                const dx = a.x - b.x, dy = a.y - b.y, dz = a.z - b.z;
                const L = Math.sqrt(dx * dx + dy * dy + dz * dz);
                shF = Math.max(0, Math.min(1, 1 - (L - S.len * 1.8) / (S.len * 2.2)));
                shF = Math.max(shF, l.hl || 0);
                alpha *= shF;
            }
            l.shF = shF;
            if (alpha < 0.01) continue;
            ctx.strokeStyle = `rgba(${col},${Math.min(0.95, alpha)})`;
            ctx.lineWidth = (0.55 + 0.35 * (l.hl || 0)) * S.linkW * (outline ? 0.8 : 1);
            if (outline) ctx.setLineDash([1, 3]);
            if (shaped) {
                // The curve's control point is the midpoint, herded toward the
                // shape itself, so a thread sags into the plane rather than
                // cutting across it.
                mp.x = (a.x + b.x) / 2; mp.y = (a.y + b.y) / 2; mp.z = (a.z + b.z) / 2;
                mp.near = false;
                if (shpNow === 'shell') {
                    const r = Math.sqrt(mp.x * mp.x + mp.y * mp.y + mp.z * mp.z) || 1;
                    const tr = (Math.hypot(a.x, a.y, a.z) + Math.hypot(b.x, b.y, b.z)) / 2;
                    const k = tr / r;
                    mp.x *= k; mp.y *= k; mp.z *= k;
                } else {
                    mp.y *= 0.35;
                    if (shpNow === 'ring') {
                        const r = Math.sqrt(mp.x * mp.x + mp.z * mp.z) || 1;
                        const tr = (Math.hypot(a.x, a.z) + Math.hypot(b.x, b.z)) / 2;
                        const k = tr / r;
                        mp.x *= k; mp.z *= k;
                    }
                }
                this.project(mp);
                ctx.beginPath();
                ctx.moveTo(a.sx, a.sy);
                ctx.quadraticCurveTo(mp.sx, mp.sy, b.sx, b.sy);
                ctx.stroke();
            } else {
                ctx.beginPath();
                ctx.moveTo(a.sx, a.sy);
                ctx.lineTo(b.sx, b.sy);
                ctx.stroke();
            }
            if (outline) ctx.setLineDash([]);
        }
    }

    // Comets: specks running along the threads. They fade with their thread rather
    // than vanishing when it does.
    private drawParticles(): void {
        const links = this.galaxy.links;
        if (!links.length) return;
        const ctx = this.ctx;
        const nodes = this.galaxy.nodes;
        for (const p of this.particles) {
            p.t += p.sp;
            if (p.t > 1) { p.t = 0; p.l = p.l + 37; }
            const l = links[p.l % links.length];
            const a = nodes[l.s], b = nodes[l.t];
            if (!a || !b || this.hidden(a) || this.hidden(b)) continue;
            const pa = 0.8 * (1 - 0.9 * (l.dm || 0)) * (l.shF === undefined ? 1 : l.shF);
            if (pa < 0.05) continue;
            const x = a.sx + (b.sx - a.sx) * p.t;
            const y = a.sy + (b.sy - a.sy) * p.t;
            const s = a.ss + (b.ss - a.ss) * p.t;
            ctx.fillStyle = `rgba(200,235,255,${pa})`;
            ctx.beginPath();
            ctx.arc(x, y, Math.max(0.5, 0.9 * s), 0, 7);
            ctx.fill();
        }
    }

    private drawStars(t: number): void {
        const ctx = this.ctx;
        const S = this.S;
        const nodes = this.galaxy.nodes;
        const W = this.W, H = this.H;

        // The glows first and all of them in screen composite: additive light is
        // order-independent, so overlapping halos physically cannot flicker
        // however the stars cross each other.
        if (S.glow > 0.01) {
            ctx.globalCompositeOperation = 'screen';
            for (const i of this.ord) {
                const n = nodes[i];
                if (!n || this.hidden(n)) continue;
                const dim = n.dim || 0;
                if (dim > 0.97) continue;
                const depth = Math.max(0.25, Math.min(1.15, 1 - n.sd / 500));
                const twA = 0.18 * S.twinkle;
                const tw = this.reduceMotion ? 1 : (1 - twA) + twA * Math.sin(t * 1.4 + n.tw * 6.283);
                const lit = 1 + 0.4 * (n.litE || 0);
                const rad = Math.min(70, n.r * n.ss * lit * S.nodeSize);
                const gr = Math.min(320, rad * (n.group === 'log' ? 4 : 6) * Math.min(1.6, S.glow));
                // The cull margin has to be bigger than the halo itself, or the
                // glows pop as they cross the screen edge.
                if (n.sx < -gr - 20 || n.sx > W + gr + 20 || n.sy < -gr - 20 || n.sy > H + gr + 20) continue;
                ctx.globalAlpha = Math.min(0.75, 0.4 * tw * depth * lit * S.glow * (1 - 0.9 * dim) * (n.nf === undefined ? 1 : n.nf));
                ctx.drawImage(this.glowFor(this.colourFn(n).css), n.sx - gr, n.sy - gr, gr * 2, gr * 2);
            }
            ctx.globalAlpha = 1;
            ctx.globalCompositeOperation = 'source-over';
        }

        for (const i of this.ord) {
            const n = nodes[i];
            if (!n || this.hidden(n)) continue;
            const look = this.colourFn(n);
            const isFocus = i === this.focusIdx;
            const dim = n.dim || 0;
            const depth = Math.max(0.25, Math.min(1.15, 1 - n.sd / 500));
            const twA = 0.18 * S.twinkle;
            const tw = this.reduceMotion ? 1 : (1 - twA) + twA * Math.sin(t * 1.4 + n.tw * 6.283);
            const lit = 1 + 0.4 * (n.litE || 0);
            const rad = Math.min(70, n.r * n.ss * lit * S.nodeSize);
            if (n.sx < -150 || n.sx > W + 150 || n.sy < -150 || n.sy > H + 150) continue;

            // A ring round the hubs and round whatever is focused.
            if ((n.w >= 14 || n.kind === 'file' || isFocus) && dim < 0.9) {
                ctx.strokeStyle = `rgba(${look.rgb},${0.55 * depth * (1 - dim)})`;
                ctx.lineWidth = 1.1;
                ctx.beginPath(); ctx.arc(n.sx, n.sy, rad * 1.9, 0, 7); ctx.stroke();
            }
            if (n.nova && dim < 0.9 && S.novas > 0.02) {
                const ph = this.reduceMotion ? 0.5 : (t * 0.28 + n.tw) % 1;
                ctx.strokeStyle = `rgba(${look.rgb},${0.35 * (1 - ph) * depth * (1 - dim) * Math.min(1.5, S.novas) * (n.nf === undefined ? 1 : n.nf)})`;
                ctx.lineWidth = 1.2;
                ctx.beginPath(); ctx.arc(n.sx, n.sy, rad * (1.6 + ph * 2.2), 0, 7); ctx.stroke();
            }
            const nf = n.nf === undefined ? 1 : n.nf;
            ctx.globalAlpha = Math.min(1, 0.35 + 0.65 * depth) * (1 - 0.55 * dim) * nf;
            ctx.fillStyle = n.group === 'log' ? `rgba(${look.rgb},0.75)` : look.css;
            ctx.beginPath(); ctx.arc(n.sx, n.sy, Math.max(0.8, rad), 0, 7); ctx.fill();
            // The white core, which is what makes a star read as a star rather
            // than as a coloured dot. Logs do not get one; that is the difference
            // between a star and an ember.
            if (n.group !== 'log' && dim < 0.95) {
                ctx.fillStyle = `rgba(255,255,255,${0.55 * tw * depth * (1 - dim) * nf})`;
                ctx.beginPath(); ctx.arc(n.sx, n.sy, rad * 0.38, 0, 7); ctx.fill();
            }
            ctx.globalAlpha = 1;
        }
    }

    // Star names, as moons: each one orbits its own star in world space, swinging
    // behind it (smaller, fainter) and in front.
    //
    // Three passes, and all three exist to stop names blinking. Which stars *want*
    // a name, with hysteresis so a threshold cannot flutter; which of those get
    // one, with current holders keeping their place so two names cannot fight over
    // the same space; and then the drawing, eased.
    private drawStarNames(t: number): void {
        const S = this.S;
        if (S.names <= 0.02) return;
        const ctx = this.ctx;
        const nodes = this.galaxy.nodes;
        const W = this.W, H = this.H;

        for (const i of this.ord) {
            const n = nodes[i];
            if (!n) continue;
            // Tiers, like a map's cities and towns: the hubs are always named, the
            // middle appears as you close in, everything else only up close.
            const tier = n.kind === 'file' || n.w >= 8 ? 1 : (n.w >= 2 && n.group !== 'log') ? 2 : 3;
            n.lblTier = tier;
            let ok = false;
            if (!this.hidden(n) && (n.dim || 0) <= 0.85
                && n.sx >= -80 && n.sx <= W + 80 && n.sy >= -60 && n.sy <= H + 60) {
                const th = [0, 0.8, 1.5, 2.3][tier];
                const sMul = n.ss * Math.sqrt(S.names);
                // Enter high, leave low - so a name on the threshold does not
                // strobe as the galaxy breathes past it.
                ok = n.lblOn ? sMul > th * 0.85 : sMul > th * 1.08;
            }
            n.lblWant = ok;
        }

        const cands: [number, number][] = [];
        for (const i of this.ord) {
            const n = nodes[i];
            if (!n) continue;
            if (!n.lblWant) { n.lblOn = false; continue; }
            cands.push([(n.lblOn ? 100000 : 0) + (3 - (n.lblTier as number)) * 1000 + n.w, i]);
        }
        cands.sort((a, b) => (b[0] - a[0]) || (a[1] - b[1]));
        const placed: { x: number; y: number; w: number; h: number }[] = [];
        const tierCount = [0, 0, 0, 0];
        for (const [, i] of cands) {
            const n = nodes[i];
            const tier = n.lblTier as number;
            if (tierCount[tier] >= TIERCAP[tier]) { n.lblOn = false; continue; }
            if (!n.lc) {
                const lbl = n.label.length > 26 ? n.label.slice(0, 24) + '…' : n.label;
                ctx.font = 'italic 100px Georgia, serif';
                const adv: number[] = [];
                let tot = 0;
                for (const chr of lbl) { const w = ctx.measureText(chr).width; adv.push(w); tot += w; }
                n.lc = { lbl, adv, tot };
            }
            const fs = (tier === 1 ? 13 : tier === 2 ? 10.5 : 9) * Math.min(1.7, Math.sqrt(n.ss));
            const wpx = n.lc.tot * (fs / 100) + fs * 0.06;
            const box = { x: n.sx - wpx / 2 - 10, y: n.sy - n.r * n.ss - fs * 2.4, w: wpx + 20, h: fs * 3 };
            let clash = false;
            for (const b of placed) {
                if (box.x < b.x + b.w && box.x + box.w > b.x && box.y < b.y + b.h && box.y + box.h > b.y) {
                    clash = true;
                    break;
                }
            }
            if (clash) { n.lblOn = false; continue; }
            placed.push(box);
            tierCount[tier]++;
            n.lblOn = true;
        }

        ctx.textAlign = 'center';
        const tmp = scratch();
        for (const i of this.ord) {
            const n = nodes[i];
            if (!n) continue;
            const tgt = n.lblOn ? 1 : 0;
            n.lblA = (n.lblA || 0) + (tgt - (n.lblA || 0)) * 0.10;
            if (n.lblA <= 0.03) continue;
            if (this.hidden(n) || !n.lc) continue;
            const ang = (this.reduceMotion ? 0 : t * 0.12) + i * 2.4;
            const rW = n.r * 2.6 + 13;
            tmp.x = n.x + Math.cos(ang) * rW;
            tmp.y = n.y - n.r * 0.8;
            tmp.z = n.z + Math.sin(ang) * rW;
            tmp.near = false;
            this.project(tmp);
            if (tmp.near) continue;
            const behind = tmp.sd > n.sd;
            const rel = Math.max(0.5, Math.min(1.4, tmp.ss / Math.max(0.001, n.ss)));
            const tier = n.lblTier as number;
            const fs = (tier === 1 ? 13 : tier === 2 ? 10.5 : 9) * Math.min(1.7, Math.sqrt(n.ss)) * rel;
            const aa = Math.min(0.85, (tier === 1 ? 0.6 : tier === 2 ? 0.5 : 0.42)
                * (1 - (n.dim || 0)) * n.lblA * (behind ? 0.4 : 1) * (tmp.nf === undefined ? 1 : tmp.nf));
            if (aa <= 0.02) continue;
            ctx.fillStyle = `rgba(${this.colourFn(n).rgb},${aa.toFixed(3)})`;
            ctx.font = `italic ${fs}px Georgia, serif`;
            ctx.fillText(n.lc.lbl, tmp.sx, tmp.sy);
        }
    }

    // The mono labels, now only for what is pointed at, focused, or soloed - the
    // orbiting names cover everything else.
    private drawLabels(): void {
        const ctx = this.ctx;
        const nodes = this.galaxy.nodes;
        const hn = this.hover >= 0 ? nodes[this.hover] : null;
        ctx.textAlign = 'center';
        ctx.lineJoin = 'round';

        const cands: [number, number][] = [];
        for (const i of this.ord) {
            const n = nodes[i];
            if (!n || this.hidden(n)) continue;
            if (n.sx < -60 || n.sx > this.W + 60 || n.sy < -40 || n.sy > this.H + 40) continue;
            let pri = -1;
            if (i === this.hover || i === this.focusIdx) pri = 1e6;
            else if (hn) { if (hn.nbr.has(i) && n.group !== 'log') pri = 1000 + n.w; }
            else if (this.solo && !this.hidden(n) && n.group !== 'log') pri = 80 + n.w;
            if (pri >= 0) cands.push([pri, i]);
        }
        cands.sort((a, b) => b[0] - a[0]);
        const placed: { x: number; y: number; w: number; h: number }[] = [];
        let drawn = 0;
        for (const [, i] of cands) {
            if (drawn >= 30) break;
            const n = nodes[i];
            const depth = Math.max(0.55, Math.min(1, 1 - n.sd / 600));
            const fs = Math.max(10, Math.min(15, (9 + n.w * 0.15) * Math.sqrt(n.ss)));
            ctx.font = `${fs}px Menlo, Consolas, monospace`;
            const label = n.label.length > 36 ? n.label.slice(0, 34) + '…' : n.label;
            const tw = ctx.measureText(label).width;
            const lx = n.sx, ly = n.sy - n.r * n.ss - 9;
            const box = { x: lx - tw / 2 - 6, y: ly - fs - 3, w: tw + 12, h: fs + 8 };
            let clash = false;
            for (const b of placed) {
                if (box.x < b.x + b.w && box.x + box.w > b.x && box.y < b.y + b.h && box.y + box.h > b.y) {
                    clash = true;
                    break;
                }
            }
            if (clash) continue;
            placed.push(box);
            drawn++;
            // Stroked behind, so a name is legible over a bright nebula.
            ctx.strokeStyle = 'rgba(3,5,10,0.85)';
            ctx.lineWidth = 3;
            ctx.strokeText(label, lx, ly);
            ctx.fillStyle = (i === this.hover || i === this.focusIdx)
                ? '#FFFFFF'
                : `rgba(226,234,248,${0.92 * depth})`;
            ctx.fillText(label, lx, ly);
        }
    }
}
