// The server's answer, turned into a galaxy.
//
// Everything here is pure and everything here is testable, which is the point:
// the engine that draws it cannot be, and a star put in the wrong constellation
// or given the wrong birthday still looks exactly like a star.

import { StarmapResult, StarmapNode as WireNode, StarmapEdge as WireEdge } from '../db';
import { LOOSE_FILES, LOOSE_HEADINGS, MAX_ANCHORS, NOVA_DAYS } from './constants';
import { Family, StarLink, StarNode } from './types';

// Which of the two things the server hands over is a constellation. The server
// sends both and calls neither one, because the right answer depends on the shape
// of the database rather than on the data - see the endpoint's own note.
export type GroupBy = 'folder' | 'file';

export interface Galaxy {
    nodes: StarNode[];
    links: StarLink[];
    families: Family[];
    // Every distinct birthday, in order. The timeline's positions.
    dates: string[];
    // How many stars carry a date somebody actually wrote down. A timeline drawn
    // over mostly-undated stars is a timeline of modification times, and the view
    // has to be able to say so rather than implying a history it has not got.
    datedCount: number;
    // The hub stars worth hanging nebula fog off.
    anchors: StarNode[];
    total: number;
    truncated: boolean;
    swallowed: number;
    eaten: string[];
    skippedLinks: number;
}

// A date as a comparable day number. Only ever used for differences, so the
// month being 31 days and the year 372 is exact enough - it cannot reorder two
// dates and it cannot be off by more than a couple of days over a span.
export function dayNumber(s: string): number {
    const p = s.split('-');
    if (p.length < 3) return 0;
    return (+p[0]) * 372 + (+p[1]) * 31 + (+p[2]);
}

// What constellation a star belongs to, and what it is called.
export function familyOf(n: WireNode, by: GroupBy): { key: string; name: string } {
    if (by === 'file') {
        // Every star has a file, so this one never falls through.
        return { key: 'f:' + n.File, name: n.File };
    }
    if (n.Folder === '') {
        return {
            key: 'd:',
            name: n.Kind === 'file' ? LOOSE_FILES : LOOSE_HEADINGS,
        };
    }
    return { key: 'd:' + n.Folder, name: n.Folder };
}

// How big a star is drawn, before the size slider and before perspective.
//
// Three things feed it and each says something different: how much is written
// under it, how many things point at it, and whether it is a note or a log. A log
// is capped small - a database with four years of day pages in it would otherwise
// be a map of its day pages.
export function radiusOf(bytes: number, inbound: number, isLog: boolean): number {
    const mass = Math.cbrt(Math.max(1, bytes || 600));
    if (isLog) return Math.min(4.2, 2.1 + mass * 0.055);
    return Math.max(3.4, 2.4 + Math.sqrt(inbound) * 1.6 + mass * 0.13);
}

// Where a star starts before the physics has said anything.
//
// A Fibonacci sphere, so the seed is evenly spread rather than clumped - and its
// radius grows with the cube root of the star count, so four thousand stars do not
// boot inside a pinhole and spend a minute exploding. A database of 150 or fewer
// is unchanged by that.
export function seedPosition(i: number, count: number): { x: number; y: number; z: number } {
    const k = i + 0.5;
    const phi = Math.acos(1 - 2 * k / Math.max(1, count));
    const th = Math.PI * (1 + Math.sqrt(5)) * k;
    const r = 120 * Math.max(1, Math.cbrt(count / 150));
    return {
        x: r * Math.sin(phi) * Math.cos(th),
        y: r * Math.sin(phi) * Math.sin(th),
        z: r * Math.cos(phi),
    };
}

// How much fog a hub deserves: what points at it, and - for a file - how much
// hangs off it, since a file that is a constellation of two headings is not one
// worth painting a cloud around.
function anchorWeight(n: StarNode): number {
    return n.w * 3 + n.nbr.size;
}

// The constellations, busiest first and by key where two are the same size, so
// the legend is stable between reads - and so the palette, which is handed out in
// this order, keeps each constellation's colour.
export function familiesOf(nodes: { fam: string; famName: string }[]): Family[] {
    const counts = new Map<string, { name: string; count: number }>();
    for (const n of nodes) {
        const e = counts.get(n.fam);
        if (e) e.count++;
        else counts.set(n.fam, { name: n.famName, count: 1 });
    }
    const out: Family[] = [];
    counts.forEach((v, key) => out.push({ key, name: v.name, count: v.count }));
    out.sort((a, b) => (b.count - a.count) || (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
    return out;
}

// What a star was doing before the last read, so a refresh does not scramble the
// galaxy. Keyed by id, and only the things a rebuild would otherwise lose.
export type Remembered = Map<string, StarNode>;

export function remember(nodes: StarNode[]): Remembered {
    const m: Remembered = new Map();
    for (const n of nodes) m.set(n.id, n);
    return m;
}

// Build the galaxy.
//
// `prev` is the last one, if there was one. Stars that are still there keep their
// exact position and motion: rebuilding from seed on every read makes the whole
// sky scramble and resettle after every edit, which is the one thing that makes a
// live map unusable.
export function buildGalaxy(
    res: StarmapResult,
    by: GroupBy,
    prev?: Remembered,
): Galaxy {
    const wire = res.Nodes || [];
    const hadPrev = prev !== undefined && prev.size > 0;
    const count = wire.length;

    const index = new Map<string, number>();
    const nodes: StarNode[] = wire.map((n, i) => {
        index.set(n.Id, i);
        const fam = familyOf(n, by);
        const isLog = n.Group === 'log';
        const seed = seedPosition(i, count);
        const star: StarNode = {
            id: n.Id,
            kind: n.Kind === 'file' ? 'file' : 'heading',
            group: isLog ? 'log' : 'note',
            label: n.Label || '(untitled)',
            filename: n.Filename,
            hash: n.Hash || '',
            line: n.Line || 0,
            level: n.Level || 0,
            path: n.Path || '',
            folder: n.Folder || '',
            file: n.File || '',
            fam: fam.key,
            status: n.Status || '',
            tags: n.Tags || [],
            bytes: n.Size || 0,
            d: n.Date || '',
            dated: !!n.Dated,
            w: n.In || 0,
            out: n.Out || 0,
            x: seed.x, y: seed.y, z: seed.z,
            vx: 0, vy: 0, vz: 0,
            // A file star is drawn as a hub whatever its own inbound count says:
            // at heading scope it is the thing every heading in the file hangs
            // off, and drawing it the size of a leaf loses the shape of the file.
            r: radiusOf(n.Size || 0, (n.In || 0) + (n.Kind === 'file' ? 6 : 0), isLog),
            deg: 1,
            nbr: new Set<number>(),
            // Golden-ratio phases, so no two neighbours twinkle together.
            tw: (i * 0.618) % 1,
            nova: false,
            sx: 0, sy: 0, ss: 1, sd: 0, near: false, nf: 1,
            vis: 1,
            isNew: false,
        };
        const old = prev && prev.get(n.Id);
        if (old) {
            star.x = old.x; star.y = old.y; star.z = old.z;
            star.vx = old.vx; star.vy = old.vy; star.vz = old.vz;
            star.dim = old.dim; star.litE = old.litE;
            star.lblA = old.lblA; star.lblOn = old.lblOn; star.lc = old.lc;
            star.tw = old.tw; star.nf = old.nf;
        } else {
            star.isNew = hadPrev;
        }
        return star;
    });

    const links: StarLink[] = [];
    for (const e of (res.Edges || []) as WireEdge[]) {
        const s = index.get(e.From);
        const t = index.get(e.To);
        if (s === undefined || t === undefined || s === t) continue;
        nodes[s].nbr.add(t);
        nodes[t].nbr.add(s);
        links.push({
            s, t,
            kind: e.Kind === 'outline' ? 'outline' : 'link',
            both: !!e.Both,
            broken: !!e.Broken,
        });
    }
    for (const n of nodes) n.deg = n.nbr.size || 1;

    // Supernovas: anything written in the last few days, measured against the
    // newest *written* date in the sky rather than against today - so a database
    // nobody has touched for a month does not simply stop having recent things,
    // and one being read on a machine with a wrong clock still works.
    let newest = '';
    let datedCount = 0;
    for (const n of nodes) {
        if (!n.dated) continue;
        datedCount++;
        if (n.d > newest) newest = n.d;
    }
    if (newest !== '') {
        const top = dayNumber(newest);
        for (const n of nodes) {
            n.nova = n.dated && top - dayNumber(n.d) <= NOVA_DAYS;
        }
    }

    // A brand new star is born beside something it is joined to rather than out
    // at the seed radius, so writing a heading lights a star where that heading
    // belongs instead of throwing one in from the rim.
    for (const n of nodes) {
        if (!n.isNew || n.nbr.size === 0) continue;
        const firstNbr = n.nbr.values().next();
        if (firstNbr.done) continue;
        const nb = nodes[firstNbr.value];
        if (!nb || nb.isNew) continue;
        n.x = nb.x + (Math.random() - 0.5) * 26;
        n.y = nb.y + (Math.random() - 0.5) * 26;
        n.z = nb.z + (Math.random() - 0.5) * 26;
    }

    const families = familiesOf(nodes.map(n => ({
        fam: n.fam,
        famName: familyOf(wire[index.get(n.id) as number], by).name,
    })));

    const dates = Array.from(new Set(nodes.map(n => n.d).filter(d => d !== ''))).sort();

    // What gets nebula fog round it.
    //
    // A hub - something much linked to, or a file, since at heading scope a file
    // is a constellation and its fog is what makes that constellation visible as
    // one thing. But capped, and the cap is not tidiness: each anchor stamps a
    // dozen 512px sprites scaled to several hundred pixels every frame, so an
    // uncapped list on a database with five hundred files is tens of thousands of
    // large composited draws a frame and the tab stops answering. The busiest
    // survive, which are the ones whose fog says something.
    const anchors = nodes
        .filter(n => n.w >= 5 || n.kind === 'file')
        .sort((a, b) => (anchorWeight(b) - anchorWeight(a)) || (a.id < b.id ? -1 : 1))
        .slice(0, MAX_ANCHORS);

    return {
        nodes, links, families, dates, datedCount, anchors,
        total: res.Total || nodes.length,
        truncated: !!res.Truncated,
        swallowed: res.Swallowed || 0,
        eaten: res.Eaten || [],
        skippedLinks: res.SkippedLinks || 0,
    };
}
