// How a todo keyword looks, wherever one is shown.
//
// The keyword is the one thing every org heading has and the thing people scan
// for, so it is drawn the same in the search table, on a kanban card and down
// the left of the list: an icon, a colour, and the word itself. Written once
// here because three tables that colour DONE three different greens teach the
// reader that the colour means nothing.
//
// A keyword nobody has thought of gets the block icon and a neutral chip, which
// is deliberate: a server's `#+TODO:` line can say anything, and an unknown
// keyword should still draw as a keyword.

import * as React from 'react';
import { ColorPaletteProp } from '@mui/joy/styles';

import CheckRoundedIcon from '@mui/icons-material/CheckRounded';
import AutorenewRoundedIcon from '@mui/icons-material/AutorenewRounded';
import BlockIcon from '@mui/icons-material/Block';
import PlayArrowRoundedIcon from '@mui/icons-material/PlayArrowRounded';
import PauseRoundedIcon from '@mui/icons-material/PauseRounded';
import CancelRoundedIcon from '@mui/icons-material/CancelRounded';
import HourglassEmptyRoundedIcon from '@mui/icons-material/HourglassEmptyRounded';
import SkipNextRoundedIcon from '@mui/icons-material/SkipNextRounded';
import RadioButtonUncheckedIcon from '@mui/icons-material/RadioButtonUnchecked';
import PhoneRoundedIcon from '@mui/icons-material/PhoneRounded';
import GroupsRoundedIcon from '@mui/icons-material/GroupsRounded';

export function getStatusIcon(status: string): React.ReactNode | undefined {
  switch (status) {
    case 'DONE': return <CheckRoundedIcon />;
    case 'IN-PROGRESS':
    case 'INPROGRESS': return <AutorenewRoundedIcon />;
    case 'TODO': return <RadioButtonUncheckedIcon />;
    case 'NEXT': return <SkipNextRoundedIcon />;
    case 'WAITING':
    case 'BLOCKED': return <HourglassEmptyRoundedIcon />;
    case 'HOLD':
    case 'PAUSED': return <PauseRoundedIcon />;
    case 'CANCELLED':
    case 'CANCELED': return <CancelRoundedIcon />;
    case 'STARTED': return <PlayArrowRoundedIcon />;
    case 'PHONE': return <PhoneRoundedIcon />;
    case 'MEETING': return <GroupsRoundedIcon />;
    default: return <BlockIcon />;
  }
}

export function getStatusColor(status: string): ColorPaletteProp | undefined {
  switch (status) {
    case 'DONE': return 'success';
    case 'IN-PROGRESS':
    case 'INPROGRESS':
    case 'STARTED': return 'warning';
    case 'TODO': return 'danger';
    case 'NEXT': return undefined; // handled via sx (cyan)
    case 'WAITING':
    case 'BLOCKED': return undefined; // handled via sx (orange/yellow)
    case 'HOLD':
    case 'PAUSED': return undefined; // handled via sx (purple)
    case 'PHONE':
    case 'MEETING': return undefined; // handled via sx (indigo)
    case 'CANCELLED':
    case 'CANCELED': return undefined; // handled via sx (plum)
    case 'BACKLOG': return undefined; // handled via sx (gold)
    default: return 'neutral';
  }
}

// The keywords org users write that the palette has no colour for. Each is a
// wash and two inks: the dark one for a light page, the light one for a dark
// page. One ink for both does not work - an orange dark enough to read on
// paper is invisible on a dark ground, and the pair is why these are written
// as a table rather than as an sx object per case.
const CUSTOM: Record<string, { bg: string; fg: string; fgDark: string }> = {
  HOLD:      { bg: 'rgba(155, 89, 182, 0.15)', fg: 'rgb(125, 60, 152)', fgDark: 'rgb(208, 154, 231)' },
  WAITING:   { bg: 'rgba(243, 156, 18, 0.15)', fg: 'rgb(211, 120, 0)',  fgDark: 'rgb(247, 187, 94)' },
  PHONE:     { bg: 'rgba(63, 81, 181, 0.18)',  fg: 'rgb(48, 63, 159)',  fgDark: 'rgb(159, 172, 242)' },
  CANCELLED: { bg: 'rgba(142, 68, 173, 0.14)', fg: 'rgb(142, 68, 173)', fgDark: 'rgb(209, 156, 228)' },
  BACKLOG:   { bg: 'rgba(184, 148, 0, 0.14)',  fg: 'rgb(164, 128, 0)',  fgDark: 'rgb(228, 198, 86)' },
  NEXT:      { bg: 'rgba(0, 188, 212, 0.14)',  fg: 'rgb(0, 151, 167)',  fgDark: 'rgb(94, 216, 233)' },
};

// The spellings that mean the same thing as one of those.
const CUSTOM_ALIAS: Record<string, string> = {
  PAUSED: 'HOLD',
  BLOCKED: 'WAITING',
  MEETING: 'PHONE',
  CANCELED: 'CANCELLED',
};

export function getStatusCustomSx(status: string): object | null {
  const key = CUSTOM_ALIAS[status] || status;
  const c = CUSTOM[key];
  if (!c) return null;
  return {
    bgcolor: c.bg,
    color: c.fg,
    // Joy stamps the scheme on an ancestor, so the dark ink is a rule rather
    // than a second call: the same chip reads on either page without whoever
    // drew it having to know which one it is on.
    '[data-joy-color-scheme="dark"] &': { color: c.fgDark },
  };
}
